/**
 * ============================================================================
 * tests/grpc-web.test.ts - gRPC-web 클라이언트 테스트
 * ============================================================================
 * Jest 기반 단위 및 통합 테스트
 * 작성: 2026-03-02
 */

import {
  GrpcWebClient,
  GrpcStatus,
  GrpcResponse,
  isGrpcResponse,
} from '../src/grpc-web/client';

/**
 * Mock 타입 정의
 */
interface GetTodoRequest {
  id: number;
}

interface GetTodoResponse {
  id: number;
  title: string;
  completed: boolean;
}

/**
 * gRPC-web 클라이언트 테스트
 */
describe('GrpcWebClient', () => {
  let client: GrpcWebClient;

  beforeEach(() => {
    client = new GrpcWebClient({
      host: 'localhost',
      port: 8080,
      useSSL: false,
      timeout: 5000,
      retries: 2,
    });
  });

  describe('클라이언트 초기화', () => {
    test('클라이언트가 올바르게 생성되어야 함', () => {
      expect(client).toBeDefined();
      expect(client.getUri()).toBe('http://localhost:8080');
    });

    test('타임아웃 설정', () => {
      client.setTimeout(10000);
      // Timeout이 설정되었는지 확인 (내부 상태)
      expect(client).toBeDefined();
    });
  });

  describe('통계', () => {
    test('초기 통계는 0이어야 함', () => {
      const stats = client.getStats();
      expect(stats.calls).toBe(0);
      expect(stats.errors).toBe(0);
      expect(stats.successRate).toBe('N/A');
    });
  });

  describe('Unary RPC', () => {
    test('성공적인 Unary 호출', async () => {
      // Mock fetch 설정
      global.fetch = jest.fn(() =>
        Promise.resolve({
          ok: true,
          json: () =>
            Promise.resolve<GetTodoResponse>({
              id: 1,
              title: 'Test Todo',
              completed: false,
            }),
        } as Response)
      );

      const request: GetTodoRequest = { id: 1 };
      const response = await client.callUnary<
        GetTodoRequest,
        GetTodoResponse
      >('TodoService', 'GetTodo', request);

      expect(response.success).toBe(true);
      expect(response.status).toBe(GrpcStatus.OK);
      expect(response.data?.title).toBe('Test Todo');
    });

    test('Unary 호출 실패 처리', async () => {
      global.fetch = jest.fn(() =>
        Promise.reject(new Error('Network error'))
      );

      const request: GetTodoRequest = { id: 999 };
      const response = await client.callUnary<
        GetTodoRequest,
        GetTodoResponse
      >('TodoService', 'GetTodo', request);

      expect(response.success).toBe(false);
      expect(response.status).toBe(GrpcStatus.UNKNOWN);
      expect(response.error).toContain('Network error');
    });
  });

  describe('타입 검증', () => {
    test('GrpcResponse 타입 가드', () => {
      const validResponse: GrpcResponse<GetTodoResponse> = {
        success: true,
        status: GrpcStatus.OK,
        data: { id: 1, title: 'Test', completed: false },
      };

      expect(isGrpcResponse(validResponse)).toBe(true);

      const invalidResponse = { foo: 'bar' };
      expect(isGrpcResponse(invalidResponse)).toBe(false);
    });
  });

  describe('메타데이터', () => {
    test('요청에 메타데이터 포함', async () => {
      global.fetch = jest.fn(() =>
        Promise.resolve({
          ok: true,
          json: () =>
            Promise.resolve<GetTodoResponse>({
              id: 1,
              title: 'Test',
              completed: false,
            }),
        } as Response)
      );

      const metadata = {
        Authorization: 'Bearer token123',
        'X-Request-ID': 'req-456',
      };

      const request: GetTodoRequest = { id: 1 };
      const response = await client.callUnary(
        'TodoService',
        'GetTodo',
        request,
        { metadata }
      );

      expect(response.success).toBe(true);
      expect(global.fetch).toHaveBeenCalledWith(
        expect.any(String),
        expect.objectContaining({
          headers: expect.objectContaining({
            Authorization: 'Bearer token123',
          }),
        })
      );
    });
  });

  describe('재시도 로직', () => {
    test('첫 실패 후 재시도 성공', async () => {
      let callCount = 0;

      global.fetch = jest.fn(() => {
        callCount++;
        if (callCount < 2) {
          return Promise.reject(new Error('Temporary error'));
        }
        return Promise.resolve({
          ok: true,
          json: () =>
            Promise.resolve<GetTodoResponse>({
              id: 1,
              title: 'Test',
              completed: false,
            }),
        } as Response);
      });

      const request: GetTodoRequest = { id: 1 };
      const response = await client.callUnary(
        'TodoService',
        'GetTodo',
        request
      );

      expect(response.success).toBe(true);
      expect(callCount).toBe(2);  // 재시도 포함
    });
  });
});

/**
 * 생성된 서비스 테스트
 */
describe('생성된 TodoService', () => {
  let client: GrpcWebClient;

  beforeEach(() => {
    client = new GrpcWebClient({
      host: 'localhost',
      port: 8080,
      useSSL: false,
    });
  });

  test('getTodo 메서드 시그니처', async () => {
    global.fetch = jest.fn(() =>
      Promise.resolve({
        ok: true,
        json: () =>
          Promise.resolve({
            success: true,
            data: { id: 1, title: 'Test', completed: false },
          }),
      } as Response)
    );

    // Generated service would look like:
    // const service = new TodoServiceClient(client);
    // const response = await service.getTodo({ id: 1 });
    // expect(response.success).toBe(true);
  });
});

/**
 * 성능 테스트
 */
describe('성능', () => {
  test('1000개 호출 처리', async () => {
    const client = new GrpcWebClient({
      host: 'localhost',
      port: 8080,
      useSSL: false,
    });

    global.fetch = jest.fn(() =>
      Promise.resolve({
        ok: true,
        json: () =>
          Promise.resolve({
            id: 1,
            title: 'Test',
            completed: false,
          }),
      } as Response)
    );

    const startTime = Date.now();

    for (let i = 0; i < 100; i++) {
      const request: GetTodoRequest = { id: i };
      await client.callUnary(
        'TodoService',
        'GetTodo',
        request
      );
    }

    const endTime = Date.now();
    const duration = endTime - startTime;

    console.log(`100 calls completed in ${duration}ms`);
    expect(duration).toBeLessThan(10000);  // 10초 이내
  });
});

/**
 * 통합 예제 코드 (문서용)
 */
describe('통합 예제', () => {
  test('Todo 생성 및 조회 흐름', async () => {
    const client = new GrpcWebClient({
      host: 'api.example.com',
      port: 443,
      useSSL: true,
      timeout: 30000,
    });

    // CreateTodo 호출
    const createResponse = await client.callUnary(
      'TodoService',
      'CreateTodo',
      { title: 'Learn gRPC-web', description: 'Study the basics' }
    );

    expect(createResponse.success).toBe(true);

    // GetTodo 호출
    const todoId = (createResponse.data as any)?.id || 1;
    const getResponse = await client.callUnary<
      GetTodoRequest,
      GetTodoResponse
    >('TodoService', 'GetTodo', { id: todoId });

    expect(getResponse.success).toBe(true);
    expect(getResponse.data?.title).toBe('Learn gRPC-web');
  });

  test('Server Streaming 예제', async () => {
    const client = new GrpcWebClient({
      host: 'localhost',
      port: 8080,
      useSSL: false,
    });

    const receivedMessages: GetTodoResponse[] = [];

    const onMessage = (message: GetTodoResponse) => {
      receivedMessages.push(message);
      console.log(`Received: ${message.title}`);
    };

    // ListTodos 스트리밍
    const response = await client.callServerStreaming(
      'TodoService',
      'ListTodos',
      {},
      onMessage
    );

    expect(response.status).toBe(GrpcStatus.OK);
  });

  test('에러 처리 예제', async () => {
    const client = new GrpcWebClient({
      host: 'localhost',
      port: 8080,
      useSSL: false,
      retries: 3,
    });

    const response = await client.callUnary<
      GetTodoRequest,
      GetTodoResponse
    >('TodoService', 'GetTodo', { id: 999 });

    if (!response.success) {
      console.error(`Error: ${response.error}`);
      console.error(`Status: ${response.status}`);
      // 사용자 정의 에러 처리
    }

    expect(response.success).toBe(false);
  });
});

