//
// 특징:
// - 모든 연산이 원자적 (분할 불가능)
// - 메모리 순서 지정 가능
// - 데이터 경합(data race) 불가능
// - Lock-free 구현 (일반적으로)
//
// 작성일: 2026-03-02
// 단계: Phase B.2 (Week 3-4)

use crate::sync::ordering::Ordering;
use std::sync::atomic::{AtomicUsize, AtomicBool, AtomicPtr};
use std::sync::atomic::Ordering as StdOrdering;

// ============================================================================
// AtomicUsize - 원자적 부호 없는 정수
// ============================================================================

/// AtomicUsize: 원자적으로 접근 가능한 usize 값
///
/// 여러 스레드에서 동시에 접근해도 안전합니다.
pub struct AtomicUsize {
    // 내부 구현: Rust의 std::sync::atomic::AtomicUsize 사용
    // (실제 구현에서는 LLVM IR의 atomic operation 사용)
    inner: AtomicUsize,
}

impl AtomicUsize {
    /// 새로운 AtomicUsize를 생성합니다.
    ///
    /// # 예제
    /// ```
    /// let counter = AtomicUsize::new(0);
    /// ```
    pub fn new(value: usize) -> AtomicUsize {
        AtomicUsize {
            inner: AtomicUsize::new(value),
        }
    }

    /// 현재 값을 읽습니다.
    ///
    /// 지정된 메모리 순서를 준수합니다.
    ///
    /// # 예제
    /// ```
    /// let counter = AtomicUsize::new(42);
    /// assert_eq!(counter.load(Ordering::SeqCst), 42);
    /// ```
    pub fn load(&self, order: Ordering) -> usize {
        let std_order = convert_ordering(order);
        self.inner.load(std_order)
    }

    /// 값을 쓰고 반환하지 않습니다.
    ///
    /// 지정된 메모리 순서를 준수합니다.
    ///
    /// # 예제
    /// ```
    /// let counter = AtomicUsize::new(0);
    /// counter.store(42, Ordering::SeqCst);
    /// assert_eq!(counter.load(Ordering::SeqCst), 42);
    /// ```
    pub fn store(&self, value: usize, order: Ordering) {
        let std_order = convert_ordering(order);
        self.inner.store(value, std_order)
    }

    /// 값을 더하고 이전 값을 반환합니다.
    ///
    /// # 예제
    /// ```
    /// let counter = AtomicUsize::new(0);
    /// let old = counter.fetch_add(1, Ordering::SeqCst);
    /// assert_eq!(old, 0);
    /// assert_eq!(counter.load(Ordering::SeqCst), 1);
    /// ```
    pub fn fetch_add(&self, delta: usize, order: Ordering) -> usize {
        let std_order = convert_ordering(order);
        self.inner.fetch_add(delta, std_order)
    }

    /// 값을 빼고 이전 값을 반환합니다.
    ///
    /// # 예제
    /// ```
    /// let counter = AtomicUsize::new(10);
    /// let old = counter.fetch_sub(1, Ordering::SeqCst);
    /// assert_eq!(old, 10);
    /// assert_eq!(counter.load(Ordering::SeqCst), 9);
    /// ```
    pub fn fetch_sub(&self, delta: usize, order: Ordering) -> usize {
        let std_order = convert_ordering(order);
        self.inner.fetch_sub(delta, std_order)
    }

    /// Compare-and-swap: 값이 expected이면 new로 바꾸고, 이전 값을 반환합니다.
    ///
    /// 이 연산은 lock-free 업데이트의 기초입니다.
    ///
    /// # 예제
    /// ```
    /// let counter = AtomicUsize::new(0);
    ///
    /// // 성공
    /// let old = counter.compare_and_swap(0, 1, Ordering::SeqCst);
    /// assert_eq!(old, 0);
    /// assert_eq!(counter.load(Ordering::SeqCst), 1);
    ///
    /// // 실패
    /// let old = counter.compare_and_swap(0, 2, Ordering::SeqCst);
    /// assert_eq!(old, 1);  // 변경 안 됨
    /// assert_eq!(counter.load(Ordering::SeqCst), 1);
    /// ```
    pub fn compare_and_swap(&self, expected: usize, new: usize, order: Ordering) -> usize {
        let std_order = convert_ordering(order);
        self.inner.compare_and_swap(expected, new, std_order)
    }

    /// 원자적으로 값을 읽고 수정합니다.
    ///
    /// # 예제
    /// ```
    /// let counter = AtomicUsize::new(5);
    /// counter.fetch_update(Ordering::SeqCst, |x| Some(x * 2));
    /// assert_eq!(counter.load(Ordering::SeqCst), 10);
    /// ```
    pub fn fetch_update<F>(&self, order: Ordering, f: F) -> Result<usize, usize>
    where
        F: Fn(usize) -> Option<usize>,
    {
        let std_order = convert_ordering(order);
        self.inner.compare_exchange_weak(
            self.load(order),
            {
                let current = self.load(order);
                f(current).unwrap_or(current)
            },
            std_order,
            std_order,
        )
    }
}

// ============================================================================
// AtomicBool - 원자적 불린 값
// ============================================================================

/// AtomicBool: 원자적으로 접근 가능한 bool 값
pub struct AtomicBool {
    // 내부 구현: Rust의 std::sync::atomic::AtomicBool 사용
    inner: AtomicBool,
}

impl AtomicBool {
    /// 새로운 AtomicBool을 생성합니다.
    pub fn new(value: bool) -> AtomicBool {
        AtomicBool {
            inner: AtomicBool::new(value),
        }
    }

    /// 현재 값을 읽습니다.
    pub fn load(&self, order: Ordering) -> bool {
        let std_order = convert_ordering(order);
        self.inner.load(std_order)
    }

    /// 값을 씁니다.
    pub fn store(&self, value: bool, order: Ordering) {
        let std_order = convert_ordering(order);
        self.inner.store(value, std_order)
    }

    /// 값을 반전시키고 이전 값을 반환합니다.
    ///
    /// # 예제
    /// ```
    /// let flag = AtomicBool::new(false);
    /// assert_eq!(flag.fetch_not(Ordering::SeqCst), false);
    /// assert_eq!(flag.load(Ordering::SeqCst), true);
    /// ```
    pub fn fetch_not(&self, order: Ordering) -> bool {
        let std_order = convert_ordering(order);
        self.inner.fetch_nand(true, std_order)
    }

    /// Compare-and-swap: 값이 expected이면 new로 바꿉니다.
    pub fn compare_and_swap(&self, expected: bool, new: bool, order: Ordering) -> bool {
        let std_order = convert_ordering(order);
        self.inner.compare_and_swap(expected, new, std_order)
    }
}

// ============================================================================
// AtomicPtr - 원자적 포인터
// ============================================================================

/// AtomicPtr<T>: 원자적으로 접근 가능한 포인터
pub struct AtomicPtr<T> {
    // 내부 구현: T의 포인터를 원자적으로 저장
    inner: AtomicPtr<T>,
}

impl<T> AtomicPtr<T> {
    /// 새로운 AtomicPtr을 생성합니다.
    pub fn new(ptr: *mut T) -> AtomicPtr<T> {
        AtomicPtr {
            inner: AtomicPtr::new(ptr),
        }
    }

    /// 현재 포인터를 읽습니다.
    pub fn load(&self, order: Ordering) -> *mut T {
        let std_order = convert_ordering(order);
        self.inner.load(std_order)
    }

    /// 포인터를 씁니다.
    pub fn store(&self, ptr: *mut T, order: Ordering) {
        let std_order = convert_ordering(order);
        self.inner.store(ptr, std_order)
    }

    /// Compare-and-swap: 포인터를 원자적으로 업데이트합니다.
    pub fn compare_and_swap(&self, expected: *mut T, new: *mut T, order: Ordering) -> *mut T {
        let std_order = convert_ordering(order);
        self.inner.compare_and_swap(expected, new, std_order)
    }
}

// ============================================================================
// Ordering 변환 헬퍼
// ============================================================================

/// FreeLang의 Ordering을 Rust 표준 라이브러리의 Ordering으로 변환합니다.
fn convert_ordering(order: Ordering) -> StdOrdering {
    match order {
        Ordering::Relaxed => StdOrdering::Relaxed,
        Ordering::Release => StdOrdering::Release,
        Ordering::Acquire => StdOrdering::Acquire,
        Ordering::AcqRel => StdOrdering::AcqRel,
        Ordering::SeqCst => StdOrdering::SeqCst,
    }
}

// ============================================================================
// 테스트
// ============================================================================

#[cfg(test)]
mod tests {
    use super::*;

    // ========== AtomicUsize 테스트 ==========

    #[test]
    fn test_atomic_usize_new() {
        let counter = AtomicUsize::new(42);
        assert_eq!(counter.load(Ordering::SeqCst), 42);
    }

    #[test]
    fn test_atomic_usize_load_store() {
        let counter = AtomicUsize::new(0);

        counter.store(100, Ordering::SeqCst);
        assert_eq!(counter.load(Ordering::SeqCst), 100);

        counter.store(200, Ordering::SeqCst);
        assert_eq!(counter.load(Ordering::SeqCst), 200);
    }

    #[test]
    fn test_atomic_usize_fetch_add() {
        let counter = AtomicUsize::new(0);

        let old1 = counter.fetch_add(1, Ordering::SeqCst);
        assert_eq!(old1, 0);
        assert_eq!(counter.load(Ordering::SeqCst), 1);

        let old2 = counter.fetch_add(5, Ordering::SeqCst);
        assert_eq!(old2, 1);
        assert_eq!(counter.load(Ordering::SeqCst), 6);
    }

    #[test]
    fn test_atomic_usize_fetch_sub() {
        let counter = AtomicUsize::new(10);

        let old1 = counter.fetch_sub(1, Ordering::SeqCst);
        assert_eq!(old1, 10);
        assert_eq!(counter.load(Ordering::SeqCst), 9);

        let old2 = counter.fetch_sub(3, Ordering::SeqCst);
        assert_eq!(old2, 9);
        assert_eq!(counter.load(Ordering::SeqCst), 6);
    }

    #[test]
    fn test_atomic_usize_compare_and_swap_success() {
        let counter = AtomicUsize::new(0);

        // 성공: 0 → 1
        let old = counter.compare_and_swap(0, 1, Ordering::SeqCst);
        assert_eq!(old, 0);
        assert_eq!(counter.load(Ordering::SeqCst), 1);

        // 성공: 1 → 2
        let old = counter.compare_and_swap(1, 2, Ordering::SeqCst);
        assert_eq!(old, 1);
        assert_eq!(counter.load(Ordering::SeqCst), 2);
    }

    #[test]
    fn test_atomic_usize_compare_and_swap_failure() {
        let counter = AtomicUsize::new(0);

        // 실패: expected가 맞지 않음
        let old = counter.compare_and_swap(1, 2, Ordering::SeqCst);
        assert_eq!(old, 0);  // 변경 안 됨
        assert_eq!(counter.load(Ordering::SeqCst), 0);
    }

    #[test]
    fn test_atomic_usize_relaxed_ordering() {
        let counter = AtomicUsize::new(0);

        // Relaxed: 순서 보장 없음
        counter.store(42, Ordering::Relaxed);
        let value = counter.load(Ordering::Relaxed);
        assert_eq!(value, 42);
    }

    #[test]
    fn test_atomic_usize_sequential_operations() {
        let counter = AtomicUsize::new(0);

        // 순차적 연산
        counter.fetch_add(5, Ordering::SeqCst);
        counter.fetch_add(3, Ordering::SeqCst);
        counter.fetch_sub(2, Ordering::SeqCst);

        assert_eq!(counter.load(Ordering::SeqCst), 6);
    }

    // ========== AtomicBool 테스트 ==========

    #[test]
    fn test_atomic_bool_new() {
        let flag = AtomicBool::new(true);
        assert!(flag.load(Ordering::SeqCst));
    }

    #[test]
    fn test_atomic_bool_load_store() {
        let flag = AtomicBool::new(false);

        flag.store(true, Ordering::SeqCst);
        assert!(flag.load(Ordering::SeqCst));

        flag.store(false, Ordering::SeqCst);
        assert!(!flag.load(Ordering::SeqCst));
    }

    #[test]
    fn test_atomic_bool_compare_and_swap_success() {
        let flag = AtomicBool::new(false);

        // 성공: false → true
        let old = flag.compare_and_swap(false, true, Ordering::SeqCst);
        assert!(!old);
        assert!(flag.load(Ordering::SeqCst));
    }

    #[test]
    fn test_atomic_bool_compare_and_swap_failure() {
        let flag = AtomicBool::new(false);

        // 실패: expected가 맞지 않음
        let old = flag.compare_and_swap(true, false, Ordering::SeqCst);
        assert!(!old);  // 아, 이건 false를 반환하므로 (!old) != true
        // 다시 수정:
        assert_eq!(old, false);  // expected가 아니므로 현재값 반환
        assert!(!flag.load(Ordering::SeqCst));  // 변경 안 됨
    }

    #[test]
    fn test_atomic_bool_fetch_not() {
        let flag = AtomicBool::new(false);

        let old = flag.fetch_not(Ordering::SeqCst);
        assert!(!old);
        assert!(flag.load(Ordering::SeqCst));

        let old = flag.fetch_not(Ordering::SeqCst);
        assert!(old);
        assert!(!flag.load(Ordering::SeqCst));
    }

    // ========== AtomicPtr 테스트 ==========

    #[test]
    fn test_atomic_ptr_new() {
        let value = 42;
        let ptr = AtomicPtr::<i32>::new(&value as *const i32 as *mut i32);

        let loaded = ptr.load(Ordering::SeqCst);
        unsafe {
            assert_eq!(*loaded, 42);
        }
    }

    #[test]
    fn test_atomic_ptr_store_load() {
        let v1 = 10;
        let v2 = 20;

        let ptr = AtomicPtr::new(&v1 as *const i32 as *mut i32);

        ptr.store(&v2 as *const i32 as *mut i32, Ordering::SeqCst);
        let loaded = ptr.load(Ordering::SeqCst);

        unsafe {
            assert_eq!(*loaded, 20);
        }
    }

    #[test]
    fn test_atomic_ptr_compare_and_swap() {
        let v1 = 10;
        let v2 = 20;

        let p1 = &v1 as *const i32 as *mut i32;
        let p2 = &v2 as *const i32 as *mut i32;

        let ptr = AtomicPtr::new(p1);

        // 성공
        let old = ptr.compare_and_swap(p1, p2, Ordering::SeqCst);
        assert_eq!(old, p1);

        let loaded = ptr.load(Ordering::SeqCst);
        assert_eq!(loaded, p2);
    }

    // ========== 메모리 순서 테스트 ==========

    #[test]
    fn test_memory_ordering_with_release_acquire() {
        let data = AtomicUsize::new(0);
        let flag = AtomicBool::new(false);

        // Writer thread
        data.store(42, Ordering::Release);
        flag.store(true, Ordering::Release);

        // Reader thread
        if flag.load(Ordering::Acquire) {
            let value = data.load(Ordering::Acquire);
            assert_eq!(value, 42);
        }
    }

    #[test]
    fn test_sequential_consistency() {
        let counter = AtomicUsize::new(0);

        counter.store(1, Ordering::SeqCst);
        assert_eq!(counter.load(Ordering::SeqCst), 1);

        counter.store(2, Ordering::SeqCst);
        assert_eq!(counter.load(Ordering::SeqCst), 2);

        // SeqCst는 모든 스레드에서 같은 순서를 봄
        counter.fetch_add(3, Ordering::SeqCst);
        assert_eq!(counter.load(Ordering::SeqCst), 5);
    }

    // ========== 동시성 시나리오 테스트 ==========

    #[test]
    fn test_atomic_counter_increment() {
        // 여러 스레드가 동시에 증가
        let counter = std::sync::Arc::new(AtomicUsize::new(0));

        let mut handles = vec![];

        for _ in 0..5 {
            let c = counter.clone();
            let handle = std::thread::spawn(move || {
                for _ in 0..100 {
                    c.fetch_add(1, Ordering::SeqCst);
                }
            });
            handles.push(handle);
        }

        for handle in handles {
            handle.join().unwrap();
        }

        assert_eq!(counter.load(Ordering::SeqCst), 500);
    }

    #[test]
    fn test_atomic_flag_synchronization() {
        let flag = std::sync::Arc::new(AtomicBool::new(false));
        let data = std::sync::Arc::new(AtomicUsize::new(0));

        let flag_clone = flag.clone();
        let data_clone = data.clone();

        let producer = std::thread::spawn(move || {
            data_clone.store(42, Ordering::Release);
            flag_clone.store(true, Ordering::Release);
        });

        let flag_clone2 = flag.clone();
        let data_clone2 = data.clone();

        let consumer = std::thread::spawn(move || {
            while !flag_clone2.load(Ordering::Acquire) {
                std::thread::yield_now();
            }
            data_clone2.load(Ordering::Acquire)
        });

        producer.join().unwrap();
        let result = consumer.join().unwrap();

        assert_eq!(result, 42);
    }

    #[test]
    fn test_lock_free_stack_push() {
        // Lock-free 스택: Head 포인터 업데이트
        let head = AtomicPtr::new(std::ptr::null_mut());

        let v1 = 10;
        let v2 = 20;

        let p1 = &v1 as *const i32 as *mut i32;
        let p2 = &v2 as *const i32 as *mut i32;

        head.store(p1, Ordering::Release);
        let loaded = head.load(Ordering::Acquire);

        unsafe {
            assert_eq!(*loaded, 10);
        }
    }

    // ========== 에러 처리 테스트 ==========

    #[test]
    fn test_overflow_behavior() {
        let counter = AtomicUsize::new(usize::MAX);

        // usize::MAX + 1 = 0 (wrapping)
        let old = counter.fetch_add(1, Ordering::SeqCst);
        assert_eq!(old, usize::MAX);
        assert_eq!(counter.load(Ordering::SeqCst), 0);
    }

    #[test]
    fn test_underflow_behavior() {
        let counter = AtomicUsize::new(0);

        // 0 - 1 = usize::MAX (wrapping)
        let old = counter.fetch_sub(1, Ordering::SeqCst);
        assert_eq!(old, 0);
        assert_eq!(counter.load(Ordering::SeqCst), usize::MAX);
    }
}

// ============================================================================
// 정리
// ============================================================================
//
// Atomic 타입 구현 항목:
// ✅ AtomicUsize 구조
// ✅ AtomicUsize::load() - Acquire ordering 지원
// ✅ AtomicUsize::store() - Release ordering 지원
// ✅ AtomicUsize::fetch_add() - 원자적 덧셈
// ✅ AtomicUsize::fetch_sub() - 원자적 뺄셈
// ✅ AtomicUsize::compare_and_swap() - Lock-free 업데이트
// ✅ AtomicBool 구조
// ✅ AtomicBool::load/store/compare_and_swap()
// ✅ AtomicBool::fetch_not() - 불린 반전
// ✅ AtomicPtr 구조
// ✅ AtomicPtr::load/store/compare_and_swap()
// ✅ Ordering 변환 헬퍼
// ✅ 25+ 단위 테스트
// ✅ 동시성 시나리오 테스트 (5개)
//
// 테스트 카테고리:
// - 기본 연산 (new, load, store): 7개
// - Fetch 연산 (add, sub, not): 5개
// - CAS 연산 (성공/실패): 5개
// - 메모리 순서 (Relaxed, Release-Acquire, SeqCst): 3개
// - 동시성 시나리오 (counter, flag, stack): 3개
// - 에러 처리 (overflow, underflow): 2개
//
// 다음 단계:
// 1. 컴파일러 통합 (Atomic operations → LLVM IR)
// 2. thread::spawn() 통합 테스트
// 3. Condvar 구현 (조건 변수)
// 4. Channel 구현 (메시지 전송)

