// ============================================================================
// FreeLang Synchronization Module (Phase B.1)
// ============================================================================
//
// 동시성 시스템의 핵심 모듈들을 정의합니다.
//
// 작성일: 2026-03-02
// 단계: Phase B.1 (Week 1-2)

pub mod traits;        // Send/Sync 트레이트
pub mod arc;           // Arc<T> - Atomic Reference Counting
pub mod mutex;         // Mutex<T> - Mutual Exclusion Lock
pub mod ordering;      // Memory ordering semantics
pub mod atomic;        // Atomic types (AtomicUsize, AtomicBool, AtomicPtr)

// Phase B.3: Lifetime tracking & Borrow Checker
pub mod borrow_state;   // Borrow 상태 관리
