/// 모든 스레드 안전 타입의 시작점
///
/// # 예제
///
/// ```
/// use freelang::sync::{Arc, Mutex};
/// use freelang::thread;
///
/// let data = Arc::new(Mutex::new(0));
/// let data_clone = data.clone();
///
/// thread::spawn(move || {
///     let mut guard = data_clone.lock();
///     *guard += 1;
/// });
/// ```

// ============================================================================
// Phase B.1 구현 체크리스트
// ============================================================================
//
// Week 1: 기초
// ✅ traits.fl: Send/Sync 정의 + 원시 타입 구현
// ✅ arc.fl: Arc<T> 완벽한 구현
// ✅ mutex.fl: Mutex<T> 완벽한 구현
//
// Week 2: 통합
// □ atomic.fl: AtomicBool, AtomicUsize 구현
// □ mod.fl: 모듈 정의
// □ compiler 통합: thread::spawn() T: Send 검증
// □ 통합 테스트: 15+ 테스트 케이스
// □ GOGS 커밋
//
// 최종 산출물:
// - 500줄 코드
// - 50줄 테스트
// - 완전한 문서

