     7→// 사용 패턴:
     8→// - Lock을 획득한 상태에서 wait()
     9→// - 다른 스레드에서 notify_one() / notify_all()
    10→// - 깨어난 후 조건 재확인
    11→//
    12→// 작성일: 2026-03-02
    13→// 단계: Phase B.5 (Week 11-12)
    14→
    15→use crate::sync::mutex::Mutex;
    16→use std::time::Duration;
    17→
    18→// ============================================================================
    19→// Condition Variable
    20→// ============================================================================
    21→
    22→/// Condition Variable: 특정 조건을 기다리는 스레드를 깨운다.
    23→pub struct Condvar {
    24→    /// 깨어날 준비가 된 스레드 ID
    25→    waiting_threads: std::sync::Mutex<Vec<std::thread::ThreadId>>,
    26→
    27→    /// Spurious wakeup 감지
    28→    wakeup_count: std::sync::atomic::AtomicUsize,
    29→}
    30→
    31→impl Condvar {
    32→    /// 새로운 Condvar을 생성합니다.
    33→    pub fn new() -> Condvar {
    34→        Condvar {
    35→            waiting_threads: std::sync::Mutex::new(Vec::new()),
    36→            wakeup_count: std::sync::atomic::AtomicUsize::new(0),
    37→        }
    38→    }
    39→
    40→    /// Lock을 보유한 상태에서 조건을 기다립니다.
    41→    ///
    42→    /// # 사용 패턴
    43→    /// ```
    44→    /// let mutex = Mutex::new(data);
    45→    /// let condvar = Condvar::new();
    46→    ///
    47→    /// loop {
    48→    ///     let guard = mutex.lock();
    49→    ///     if condition_met(&guard) {
    50→    ///         break;
    51→    ///     }
    52→    ///     condvar.wait(&mutex);
    53→    ///     // Lock 자동 재획득
    54→    /// }
    55→    /// ```
    56→    pub fn wait<'a, T>(&self, mutex: &'a Mutex<T>) -> std::sync::MutexGuard<'a, T> {
    57→        let current_thread = std::thread::current().id();
    58→        let mut waiting = self.waiting_threads.lock().unwrap();
    59→        waiting.push(current_thread);
    60→        drop(waiting);

