    53→/// HMAC-like function (simplified)
    54→pub fn hmac(args: Vec<Value>) -> Result<Value, String> {
    55→    if args.len() < 2 {
    56→        return Err("hmac requires 2 arguments: message, key".to_string());
    57→    }
    58→
    59→    let message = args[0].to_string();
    60→    let key = args[1].to_string();
    61→
    62→    // Simple HMAC-like: hash(key + message + key)
    63→    let combined = format!("{}{}{}", key, message, key);
    64→    let mut hasher = DefaultHasher::new();
    65→    combined.hash(&mut hasher);
    66→    let hash_value = hasher.finish();
    67→
    68→    Ok(Value::String(format!("{:x}", hash_value)))
    69→}
