// ============================================================================
// FreeLang Standard Library Module (Phase C.1)
// ============================================================================
//
// 105+ 내장 함수를 제공하는 표준 라이브러리
// Phase B sync 모듈과 통합 가능한 설계
//
// 작성일: 2026-03-02
// 단계: Phase C (Week 1-4)

pub mod types;    // 타입 변환 (6개)
pub mod io;       // 파일/콘솔 I/O (15개)
pub mod math;     // 수학 함수 (20개)
pub mod string;   // 문자열 처리 (18개)
pub mod array;    // 배열 조작 (18개)
pub mod time;     // 시간 처리 (5개)
pub mod system;   // 시스템 호출 (8개)
pub mod json;     // JSON 처리 (6개)
pub mod object;   // 객체/맵 처리 (5개)
pub mod error;    // 에러 처리 (4개)

// ============================================================================
// FlValue Type - 모든 stdlib 함수가 사용하는 통일된 값 타입
// ============================================================================

/// FreeLang 값의 통일된 표현
#[derive(Clone, Debug, PartialEq)]
pub enum FlValue {
    /// 정수 (i64)
    Int(i64),

    /// 부동소수점 (f64)
    Float(f64),

    /// 불리언
    Bool(bool),

    /// 문자열
    Str(String),

    /// 배열
    Array(Vec<FlValue>),

    /// 객체/맵 (키-값 쌍)
    Object(std::collections::HashMap<String, FlValue>),

    /// null 값
    Null,
}

impl FlValue {
    /// 값의 타입명을 반환합니다.
    pub fn type_name(&self) -> &'static str {
        match self {
            FlValue::Int(_) => "int",
            FlValue::Float(_) => "float",
            FlValue::Bool(_) => "bool",
            FlValue::Str(_) => "string",
            FlValue::Array(_) => "array",
            FlValue::Object(_) => "object",
            FlValue::Null => "null",
        }
    }

    /// 값이 "참"인지 확인합니다 (Truthy evaluation).
    pub fn is_truthy(&self) -> bool {
        match self {
            FlValue::Null => false,
            FlValue::Bool(b) => *b,
            FlValue::Int(n) => *n != 0,
            FlValue::Float(f) => *f != 0.0,
            FlValue::Str(s) => !s.is_empty(),
            FlValue::Array(arr) => !arr.is_empty(),
            FlValue::Object(obj) => !obj.is_empty(),
        }
    }

    /// 값이 null인지 확인합니다.
    pub fn is_null(&self) -> bool {
        matches!(self, FlValue::Null)
    }

    /// 값의 문자열 표현을 반환합니다.
    pub fn to_string_repr(&self) -> String {
        match self {
            FlValue::Null => "null".to_string(),
            FlValue::Bool(b) => b.to_string(),
            FlValue::Int(n) => n.to_string(),
            FlValue::Float(f) => f.to_string(),
            FlValue::Str(s) => s.clone(),
            FlValue::Array(_) => format!("[array]"),
            FlValue::Object(_) => format!("[object]"),
        }
    }
}

/// 표준 라이브러리 정보를 반환합니다.
pub fn stdlib_info() -> &'static str {
    "FreeLang stdlib v1.0 - Phase C (105+ 함수)"
}

