pub fn round(value: FlValue) -> Result<FlValue, MathError> {
    match value {
        FlValue::Int(n) => Ok(FlValue::Int(n)),
        FlValue::Float(f) => Ok(FlValue::Int(f.round() as i64)),
        _ => Err(MathError::DomainError("round requires numeric value".to_string())),
    }
}

