pub fn tan(value: FlValue) -> Result<FlValue, MathError> {
    match value {
        FlValue::Int(n) => Ok(FlValue::Float((n as f64).tan())),
        FlValue::Float(f) => Ok(FlValue::Float(f.tan())),
        _ => Err(MathError::DomainError("tan requires numeric value".to_string())),
    }
}

/// 역사인(asin)을 반환합니다 (라디안 반환).
///
/// # 에러
/// - 범위 밖: MathError::DomainError
///
/// # 예제
/// ```
/// assert_eq!(asin(FlValue::Float(0.0)), Ok(FlValue::Float(0.0)));
/// assert_eq!(asin(FlValue::Float(2.0)), Err(MathError::DomainError(_)));
/// ```
pub fn asin(value: FlValue) -> Result<FlValue, MathError> {
    match value {
        FlValue::Int(n) => {
            let f = n as f64;
            if f < -1.0 || f > 1.0 {
                Err(MathError::DomainError("asin domain: [-1, 1]".to_string()))
            } else {
                Ok(FlValue::Float(f.asin()))
            }
        }
        FlValue::Float(f) => {
            if f < -1.0 || f > 1.0 {
                Err(MathError::DomainError("asin domain: [-1, 1]".to_string()))
            } else {
                Ok(FlValue::Float(f.asin()))
            }
        }
        _ => Err(MathError::DomainError("asin requires numeric value".to_string())),
    }
}

/// 역코사인(acos)을 반환합니다 (라디안 반환).
///
/// # 에러
/// - 범위 밖: MathError::DomainError
pub fn acos(value: FlValue) -> Result<FlValue, MathError> {
    match value {
        FlValue::Int(n) => {
            let f = n as f64;
            if f < -1.0 || f > 1.0 {
                Err(MathError::DomainError("acos domain: [-1, 1]".to_string()))
            } else {
                Ok(FlValue::Float(f.acos()))
            }
        }
        FlValue::Float(f) => {
            if f < -1.0 || f > 1.0 {
                Err(MathError::DomainError("acos domain: [-1, 1]".to_string()))
            } else {
                Ok(FlValue::Float(f.acos()))
            }
        }
        _ => Err(MathError::DomainError("acos requires numeric value".to_string())),
    }
}

/// 역탄젠트(atan)를 반환합니다 (라디안 반환).
///
/// # 예제
/// ```
/// assert_eq!(atan(FlValue::Float(0.0)), Ok(FlValue::Float(0.0)));
/// ```
pub fn atan(value: FlValue) -> Result<FlValue, MathError> {
    match value {
        FlValue::Int(n) => Ok(FlValue::Float((n as f64).atan())),
        FlValue::Float(f) => Ok(FlValue::Float(f.atan())),
        _ => Err(MathError::DomainError("atan requires numeric value".to_string())),
    }
}

/// 두 인자의 역탄젠트(atan2)를 반환합니다 (y, x 순서, 라디안 반환).
///
/// # 예제
/// ```
/// assert_eq!(atan2(FlValue::Int(0), FlValue::Int(1)), Ok(FlValue::Float(0.0)));
/// ```
pub fn atan2(y: FlValue, x: FlValue) -> Result<FlValue, MathError> {
    let y_f = match y {
        FlValue::Int(n) => n as f64,
        FlValue::Float(f) => f,
        _ => return Err(MathError::DomainError("atan2 y must be numeric".to_string())),
    };

    let x_f = match x {
        FlValue::Int(n) => n as f64,
        FlValue::Float(f) => f,
        _ => return Err(MathError::DomainError("atan2 x must be numeric".to_string())),
    };

    Ok(FlValue::Float(y_f.atan2(x_f)))
}

// ============================================================================
// Logarithmic and Exponential Functions
// ============================================================================

/// 자연로그(ln)를 반환합니다.
///
/// # 에러
/// - 0 이하: MathError::DomainError
///
/// # 예제
/// ```
/// assert_eq!(ln(FlValue::Float(1.0)), Ok(FlValue::Float(0.0)));
/// ```
pub fn ln(value: FlValue) -> Result<FlValue, MathError> {
    match value {
        FlValue::Int(n) => {
            if n <= 0 {
                Err(MathError::DomainError("ln domain: (0, ∞)".to_string()))
            } else {
                Ok(FlValue::Float((n as f64).ln()))
            }
        }
        FlValue::Float(f) => {
            if f <= 0.0 {
                Err(MathError::DomainError("ln domain: (0, ∞)".to_string()))
            } else {
                Ok(FlValue::Float(f.ln()))
            }
        }
        _ => Err(MathError::DomainError("ln requires numeric value".to_string())),
    }
}

/// 상용로그(log10)을 반환합니다.
///
/// # 에러
/// - 0 이하: MathError::DomainError
pub fn log10(value: FlValue) -> Result<FlValue, MathError> {
    match value {
        FlValue::Int(n) => {
            if n <= 0 {
                Err(MathError::DomainError("log10 domain: (0, ∞)".to_string()))
            } else {
                Ok(FlValue::Float((n as f64).log10()))
            }
        }
        FlValue::Float(f) => {
            if f <= 0.0 {
                Err(MathError::DomainError("log10 domain: (0, ∞)".to_string()))
