/// 지수함수(e^x)를 반환합니다.
///
/// # 예제
/// ```
/// assert_eq!(exp(FlValue::Float(0.0)), Ok(FlValue::Float(1.0)));
/// ```
pub fn exp(value: FlValue) -> Result<FlValue, MathError> {
    match value {
        FlValue::Int(n) => Ok(FlValue::Float((n as f64).exp())),
        FlValue::Float(f) => Ok(FlValue::Float(f.exp())),
        _ => Err(MathError::DomainError("exp requires numeric value".to_string())),
    }
