pub fn sin(value: FlValue) -> Result<FlValue, MathError> {
    match value {
        FlValue::Int(n) => Ok(FlValue::Float((n as f64).sin())),
        FlValue::Float(f) => Ok(FlValue::Float(f.sin())),
        _ => Err(MathError::DomainError("sin requires numeric value".to_string())),
    }
}

/// 코사인(cos)을 반환합니다 (라디안 입력).
///
/// # 예제
