pub fn cos(value: FlValue) -> Result<FlValue, MathError> {
    match value {
        FlValue::Int(n) => Ok(FlValue::Float((n as f64).cos())),
        FlValue::Float(f) => Ok(FlValue::Float(f.cos())),
        _ => Err(MathError::DomainError("cos requires numeric value".to_string())),
    }
}

/// 탄젠트(tan)를 반환합니다 (라디안 입력).
///
/// # 예제
/// ```
/// assert_eq!(tan(FlValue::Float(0.0)), FlValue::Float(0.0));
/// ```
pub fn tan(value: FlValue) -> Result<FlValue, MathError> {
    match value {
        FlValue::Int(n) => Ok(FlValue::Float((n as f64).tan())),
        FlValue::Float(f) => Ok(FlValue::Float(f.tan())),
        _ => Err(MathError::DomainError("tan requires numeric value".to_string())),
    }
}

/// 역사인(asin)을 반환합니다 (라디안 반환).
///
/// # 에러
/// - 범위 밖: MathError::DomainError
///
/// # 예제
/// ```
/// assert_eq!(asin(FlValue::Float(0.0)), Ok(FlValue::Float(0.0)));
/// assert_eq!(asin(FlValue::Float(2.0)), Err(MathError::DomainError(_)));
/// ```
pub fn asin(value: FlValue) -> Result<FlValue, MathError> {
    match value {
        FlValue::Int(n) => {
            let f = n as f64;
            if f < -1.0 || f > 1.0 {
                Err(MathError::DomainError("asin domain: [-1, 1]".to_string()))
            } else {
                Ok(FlValue::Float(f.asin()))
            }
        }
        FlValue::Float(f) => {
            if f < -1.0 || f > 1.0 {
                Err(MathError::DomainError("asin domain: [-1, 1]".to_string()))
            } else {
                Ok(FlValue::Float(f.asin()))
            }
        }
        _ => Err(MathError::DomainError("asin requires numeric value".to_string())),
    }
}

/// 역코사인(acos)을 반환합니다 (라디안 반환).
///
/// # 에러
/// - 범위 밖: MathError::DomainError
pub fn acos(value: FlValue) -> Result<FlValue, MathError> {
    match value {
        FlValue::Int(n) => {
            let f = n as f64;
            if f < -1.0 || f > 1.0 {
