// ============================================================================
// FreeLang Standard Library - array.fl
// ============================================================================
//
// 배열 조작 함수 (18개, 고차함수 포함)
// freelang-runtime/src/stdlib/array.rs 참조
//
// 작성일: 2026-03-02
// 단계: Phase C.2 (Week 2)

use std::collections::HashSet;
use crate::stdlib::FlValue;

// ============================================================================
// ArrayError - 배열 처리 에러 타입
// ============================================================================

/// 배열 처리 시 발생할 수 있는 에러
#[derive(Clone, Debug, PartialEq)]
pub enum ArrayError {
    /// 인덱스 범위 초과
    IndexOutOfBounds { index: i64, len: i64 },

    /// 빈 배열에서 pop 시도
    EmptyArray,

    /// 타입 불일치
    TypeMismatch(String),
}

impl std::fmt::Display for ArrayError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            ArrayError::IndexOutOfBounds { index, len } => {
                write!(f, "Index {} out of bounds (length {})", index, len)
            }
            ArrayError::EmptyArray => write!(f, "Cannot pop from empty array"),
            ArrayError::TypeMismatch(msg) => write!(f, "Type mismatch: {}", msg),
        }
    }
}

// ============================================================================
// Basic Array Functions (CRUD)
// ============================================================================

/// 배열의 길이를 반환합니다.
///
/// # 예제
/// ```
/// let arr = FlValue::Array(vec![FlValue::Int(1), FlValue::Int(2)]);
/// assert_eq!(array_length(arr), 2);
/// ```
pub fn array_length(arr: FlValue) -> Result<i64, ArrayError> {
    match arr {
        FlValue::Array(elements) => Ok(elements.len() as i64),
        _ => Err(ArrayError::TypeMismatch("Expected array".to_string())),
    }
}

/// 배열에 요소를 추가합니다 (뒤에 추가).
///
/// # 예제
/// ```
/// let mut arr = vec![FlValue::Int(1), FlValue::Int(2)];
/// push(&mut arr, FlValue::Int(3));
/// assert_eq!(arr.len(), 3);
/// ```
pub fn push(arr: &mut Vec<FlValue>, item: FlValue) {
    arr.push(item);
}

/// 배열의 마지막 요소를 제거하고 반환합니다.
///
/// # 에러
/// - 빈 배열: ArrayError::EmptyArray
///
/// # 예제
/// ```
/// let mut arr = vec![FlValue::Int(1), FlValue::Int(2)];
/// assert_eq!(pop(&mut arr).unwrap(), FlValue::Int(2));
/// ```
pub fn pop(arr: &mut Vec<FlValue>) -> Result<FlValue, ArrayError> {
    arr.pop().ok_or(ArrayError::EmptyArray)
}

/// 배열의 특정 인덱스에 있는 요소를 반환합니다.
///
/// # 에러
/// - 범위 초과: ArrayError::IndexOutOfBounds
///
/// # 예제
/// ```
/// let arr = vec![FlValue::Int(10), FlValue::Int(20), FlValue::Int(30)];
/// assert_eq!(get(arr, 1).unwrap(), FlValue::Int(20));
/// ```
pub fn get(arr: FlValue, index: i64) -> Result<FlValue, ArrayError> {
    match arr {
        FlValue::Array(elements) => {
            if index < 0 || index >= elements.len() as i64 {
                return Err(ArrayError::IndexOutOfBounds {
                    index,
                    len: elements.len() as i64,
                });
            }
            Ok(elements[index as usize].clone())
        }
        _ => Err(ArrayError::TypeMismatch("Expected array".to_string())),
    }
}

/// 배열의 특정 인덱스의 요소를 설정합니다.
///
/// # 에러
/// - 범위 초과: ArrayError::IndexOutOfBounds
///
/// # 예제
/// ```
/// let mut arr = vec![FlValue::Int(1), FlValue::Int(2)];
/// set(&mut arr, 0, FlValue::Int(10)).unwrap();
/// ```
pub fn set(arr: &mut Vec<FlValue>, index: i64, value: FlValue) -> Result<(), ArrayError> {
    if index < 0 || index >= arr.len() as i64 {
        return Err(ArrayError::IndexOutOfBounds {
            index,
            len: arr.len() as i64,
        });
    }
    arr[index as usize] = value;
    Ok(())
}

// ============================================================================
// Array Transformation Functions
// ============================================================================

/// 배열의 부분 배열을 추출합니다.
///
/// # 매개변수
/// - start: 시작 인덱스 (포함)
/// - end: 종료 인덱스 (포함)
///
/// # 에러
/// - 범위 초과: ArrayError::IndexOutOfBounds
///
/// # 예제
/// ```
/// let arr = vec![1, 2, 3, 4, 5];
/// assert_eq!(slice(arr, 1, 3), vec![2, 3, 4]);
/// ```
pub fn slice(arr: FlValue, start: i64, end: i64) -> Result<FlValue, ArrayError> {
    match arr {
        FlValue::Array(elements) => {
            let len = elements.len() as i64;
            if start < 0 || end < 0 || start > len || end > len || start > end {
                return Err(ArrayError::IndexOutOfBounds {
                    index: if start < 0 || start > len { start } else { end },
                    len,
                });
            }

            let sliced: Vec<FlValue> = elements.iter()
                .skip(start as usize)
                .take((end - start + 1) as usize)
                .cloned()
                .collect();

            Ok(FlValue::Array(sliced))
        }
        _ => Err(ArrayError::TypeMismatch("Expected array".to_string())),
    }
}

/// 배열을 정렬합니다 (숫자는 오름차순, 문자열은 사전순).
///
/// # 주의
/// - 다른 타입이 섞여 있으면 정렬 순서는 정의되지 않음
///
/// # 예제
/// ```
/// let arr = vec![FlValue::Int(3), FlValue::Int(1), FlValue::Int(2)];
/// assert_eq!(sort(arr).unwrap()[0], FlValue::Int(1));
/// ```
pub fn sort(arr: FlValue) -> Result<FlValue, ArrayError> {
    match arr {
        FlValue::Array(mut elements) => {
            elements.sort_by(|a, b| {
                match (a, b) {
                    (FlValue::Int(x), FlValue::Int(y)) => x.cmp(y),
                    (FlValue::Float(x), FlValue::Float(y)) => {
                        x.partial_cmp(y).unwrap_or(std::cmp::Ordering::Equal)
                    }
                    (FlValue::Str(x), FlValue::Str(y)) => x.cmp(y),
                    (FlValue::Bool(x), FlValue::Bool(y)) => x.cmp(y),
                    _ => std::cmp::Ordering::Equal,
                }
            });
            Ok(FlValue::Array(elements))
        }
        _ => Err(ArrayError::TypeMismatch("Expected array".to_string())),
    }
}

/// 배열의 요소들을 역순으로 정렬합니다.
///
/// # 예제
/// ```
/// let arr = vec![FlValue::Int(1), FlValue::Int(2), FlValue::Int(3)];
/// assert_eq!(array_reverse(arr).unwrap()[0], FlValue::Int(3));
/// ```
pub fn array_reverse(arr: FlValue) -> Result<FlValue, ArrayError> {
    match arr {
        FlValue::Array(mut elements) => {
            elements.reverse();
            Ok(FlValue::Array(elements))
        }
        _ => Err(ArrayError::TypeMismatch("Expected array".to_string())),
    }
}

// ============================================================================
// Higher-Order Functions (고차함수)
// ============================================================================

/// 배열의 각 요소에 함수를 적용하여 새 배열을 반환합니다.
///
/// # 매개변수
/// - arr: 배열
/// - f: 각 요소에 적용할 함수 (FlValue -> FlValue)
///
/// # 예제
/// ```
/// let arr = vec![FlValue::Int(1), FlValue::Int(2), FlValue::Int(3)];
/// let result = map(FlValue::Array(arr), |x| {
///     match x {
///         FlValue::Int(n) => FlValue::Int(n * 2),
///         _ => x,
///     }
/// }).unwrap();
/// ```
pub fn map<F>(arr: FlValue, f: F) -> Result<FlValue, ArrayError>
where
    F: Fn(FlValue) -> FlValue,
{
    match arr {
        FlValue::Array(elements) => {
            let mapped: Vec<FlValue> = elements.iter()
                .map(|elem| f(elem.clone()))
                .collect();
            Ok(FlValue::Array(mapped))
        }
        _ => Err(ArrayError::TypeMismatch("Expected array".to_string())),
    }
}

/// 조건을 만족하는 요소들만 필터링하여 새 배열을 반환합니다.
///
/// # 매개변수
/// - arr: 배열
/// - f: 각 요소를 평가할 함수 (FlValue -> bool)
///
/// # 예제
/// ```
/// let arr = vec![FlValue::Int(1), FlValue::Int(2), FlValue::Int(3)];
/// let result = filter(FlValue::Array(arr), |x| {
///     match x {
///         FlValue::Int(n) => n > 1,
///         _ => false,
///     }
/// }).unwrap();
/// ```
pub fn filter<F>(arr: FlValue, f: F) -> Result<FlValue, ArrayError>
where
    F: Fn(&FlValue) -> bool,
{
    match arr {
        FlValue::Array(elements) => {
            let filtered: Vec<FlValue> = elements.iter()
                .filter(|elem| f(elem))
                .cloned()
                .collect();
            Ok(FlValue::Array(filtered))
        }
        _ => Err(ArrayError::TypeMismatch("Expected array".to_string())),
    }
}

/// 배열의 요소들을 순회하면서 축적(reduce)합니다.
///
/// # 매개변수
/// - arr: 배열
/// - f: 축적 함수 ((accumulator, current) -> new_accumulator)
/// - init: 초기값
///
/// # 예제
/// ```
/// let arr = vec![FlValue::Int(1), FlValue::Int(2), FlValue::Int(3)];
/// let result = reduce(FlValue::Array(arr), |acc, x| {
///     match (acc, x) {
///         (FlValue::Int(a), FlValue::Int(b)) => FlValue::Int(a + b),
///         _ => acc,
///     }
/// }, FlValue::Int(0)).unwrap();
/// assert_eq!(result, FlValue::Int(6));
/// ```
pub fn reduce<F>(arr: FlValue, f: F, init: FlValue) -> Result<FlValue, ArrayError>
where
    F: Fn(FlValue, FlValue) -> FlValue,
{
    match arr {
        FlValue::Array(elements) => {
            let result = elements.iter()
                .fold(init, |acc, elem| f(acc, elem.clone()));
            Ok(result)
        }
        _ => Err(ArrayError::TypeMismatch("Expected array".to_string())),
    }
}

// ============================================================================
// Search and Lookup
// ============================================================================

/// 배열이 특정 요소를 포함하는지 확인합니다.
///
/// # 예제
/// ```
/// let arr = vec![FlValue::Int(1), FlValue::Int(2), FlValue::Int(3)];
/// assert_eq!(array_contains(arr, FlValue::Int(2)), true);
/// assert_eq!(array_contains(arr, FlValue::Int(5)), false);
/// ```
pub fn array_contains(arr: FlValue, item: FlValue) -> bool {
    match arr {
        FlValue::Array(elements) => elements.iter().any(|elem| elem == &item),
        _ => false,
    }
}

/// 배열에서 요소의 인덱스를 반환합니다.
///
/// # 반환값
/// - 찾으면: 인덱스 (0부터 시작)
/// - 못 찾으면: -1
///
/// # 예제
/// ```
/// let arr = vec![FlValue::Int(10), FlValue::Int(20), FlValue::Int(30)];
/// assert_eq!(array_index_of(arr, FlValue::Int(20)), 1);
/// assert_eq!(array_index_of(arr, FlValue::Int(99)), -1);
/// ```
pub fn array_index_of(arr: FlValue, item: FlValue) -> i64 {
    match arr {
        FlValue::Array(elements) => {
            for (i, elem) in elements.iter().enumerate() {
                if elem == &item {
                    return i as i64;
                }
            }
            -1
        }
        _ => -1,
    }
}

// ============================================================================
// Advanced Array Functions
// ============================================================================

/// 중첩 배열을 한 단계 펼칩니다.
///
/// # 예제
/// ```
/// let arr = vec![
///     FlValue::Array(vec![FlValue::Int(1), FlValue::Int(2)]),
///     FlValue::Array(vec![FlValue::Int(3), FlValue::Int(4)]),
/// ];
/// assert_eq!(flat(FlValue::Array(arr)).unwrap().len(), 4);
/// ```
pub fn flat(arr: FlValue) -> Result<FlValue, ArrayError> {
    match arr {
        FlValue::Array(elements) => {
            let mut flattened = Vec::new();
            for elem in elements {
                match elem {
                    FlValue::Array(inner) => {
                        flattened.extend(inner);
                    }
                    other => {
                        flattened.push(other);
                    }
                }
            }
            Ok(FlValue::Array(flattened))
        }
        _ => Err(ArrayError::TypeMismatch("Expected array".to_string())),
    }
}

/// 배열의 중복 요소를 제거합니다.
///
/// # 주의
/// - 순서는 보장되지 않음 (HashSet 기반)
///
/// # 예제
/// ```
/// let arr = vec![FlValue::Int(1), FlValue::Int(2), FlValue::Int(1), FlValue::Int(3)];
/// let result = unique(FlValue::Array(arr)).unwrap();
/// ```
pub fn unique(arr: FlValue) -> Result<FlValue, ArrayError> {
    match arr {
        FlValue::Array(elements) => {
            let mut seen = std::collections::HashSet::new();
            let mut unique_vec = Vec::new();

            for elem in elements {
                let key = elem.to_string_repr();
                if seen.insert(key) {
                    unique_vec.push(elem);
                }
            }

            Ok(FlValue::Array(unique_vec))
        }
        _ => Err(ArrayError::TypeMismatch("Expected array".to_string())),
    }
}

/// 두 배열의 요소를 쌍으로 묶습니다.
///
/// # 반환값
/// - 더 짧은 배열의 길이만큼 쌍을 생성
///
/// # 예제
/// ```
/// let arr1 = vec![FlValue::Int(1), FlValue::Int(2)];
/// let arr2 = vec![FlValue::Str("a".to_string()), FlValue::Str("b".to_string())];
/// let result = zip(FlValue::Array(arr1), FlValue::Array(arr2)).unwrap();
/// ```
pub fn zip(arr1: FlValue, arr2: FlValue) -> Result<FlValue, ArrayError> {
    match (arr1, arr2) {
        (FlValue::Array(elements1), FlValue::Array(elements2)) => {
            let min_len = elements1.len().min(elements2.len());
            let mut pairs = Vec::new();

            for i in 0..min_len {
                let pair = FlValue::Array(vec![
                    elements1[i].clone(),
                    elements2[i].clone(),
                ]);
                pairs.push(pair);
            }

            Ok(FlValue::Array(pairs))
        }
        _ => Err(ArrayError::TypeMismatch("Expected arrays".to_string())),
    }
}

// ============================================================================
// Array Combination Functions
// ============================================================================

/// 배열을 문자열로 연결합니다.
///
/// # 예제
/// ```
/// let arr = vec![FlValue::Int(1), FlValue::Int(2), FlValue::Int(3)];
/// assert_eq!(array_join(arr, ","), "1,2,3");
/// ```
pub fn array_join(arr: FlValue, delim: String) -> String {
    match arr {
        FlValue::Array(elements) => {
            let strings: Vec<String> = elements.iter()
                .map(|elem| elem.to_string_repr())
                .collect();
            strings.join(&delim)
        }
        _ => String::new(),
    }
}

/// 두 배열을 연결합니다.
///
/// # 예제
/// ```
/// let arr1 = vec![FlValue::Int(1), FlValue::Int(2)];
/// let arr2 = vec![FlValue::Int(3), FlValue::Int(4)];
/// let result = array_concat(arr1, arr2);
/// ```
pub fn array_concat(arr1: FlValue, arr2: FlValue) -> Result<FlValue, ArrayError> {
    match (arr1, arr2) {
        (FlValue::Array(mut elements1), FlValue::Array(elements2)) => {
            elements1.extend(elements2);
            Ok(FlValue::Array(elements1))
        }
        _ => Err(ArrayError::TypeMismatch("Expected arrays".to_string())),
    }
}

// ============================================================================
// 테스트
// ============================================================================

