use crate::fpm::{
    FpmError, FPM_VERSION, DEFAULT_REGISTRY_URL,
};
use crate::fpm::parser;
use crate::fpm::registry;
use crate::fpm::resolver;

// ============================================================================
// CLI Result
// ============================================================================

#[derive(Clone, Debug)]
pub struct CliResult {
    pub success: bool,
    pub message: String,
    pub details: Vec<String>,
}

impl CliResult {
    pub fn ok(message: &str) -> Self {
        CliResult {
            success: true,
            message: message.to_string(),
            details: vec![],
        }
    }

    pub fn error(message: &str) -> Self {
        CliResult {
            success: false,
            message: message.to_string(),
            details: vec![],
        }
    }

    pub fn with_details(mut self, details: Vec<String>) -> Self {
        self.details = details;
        self
    }
}

// ============================================================================
// CLI Commands
// ============================================================================

/// fpm init - 새 FreeLang 프로젝트 초기화
pub fn cmd_init(
    project_name: &str,
    author: &str,
) -> CliResult {
    // freelang.toml 생성
    let manifest_content = format!(
        r#"[package]
name = "{}"
version = "0.1.0"
author = "{}"
description = "A FreeLang project"

[dependencies]
"#,
        project_name, author
    );

    // 파일 저장 (mock)
    println!("Creating freelang.toml...");
    println!("{}", manifest_content);

    CliResult::ok(&format!(
        "Initialized new project '{}' with author '{}'",
        project_name, author
    ))
}

/// fpm add - 의존성 추가
pub fn cmd_add(
    manifest_path: &str,
    package_name: &str,
    version_range: &str,
) -> CliResult {
    // 패키지명 검증
    if !registry::is_valid_package_name(package_name) {
        return CliResult::error(&format!(
            "Invalid package name: '{}' (must be lowercase with hyphens)",
            package_name
        ));
    }

    // 버전 범위 검증
    match resolver::parse_version_range(version_range) {
        Ok(_) => {
            CliResult::ok(&format!(
                "Added dependency '{}' with version range '{}'",
                package_name, version_range
            ))
            .with_details(vec![
                format!("Package: {}", package_name),
                format!("Version: {}", version_range),
                format!("Manifest: {}", manifest_path),
            ])
        }
        Err(e) => {
            CliResult::error(&format!(
                "Invalid version range '{}': {}",
                version_range, e
            ))
        }
    }
}

/// fpm install - 의존성 설치
pub fn cmd_install(manifest_path: &str) -> CliResult {
    // freelang.toml 읽기
    println!("Reading {}...", manifest_path);

    // 의존성 해결
    println!("Resolving dependencies...");

    // Mock: 성공 결과
    CliResult::ok("Installed all dependencies successfully")
        .with_details(vec![
            "✓ freelang-json@1.2.3".to_string(),
            "✓ freelang-http@2.1.0".to_string(),
            "Total: 2 packages installed".to_string(),
        ])
}

/// fpm publish - 패키지 발행
pub fn cmd_publish(manifest_path: &str) -> CliResult {
    // freelang.toml 읽기
    println!("Reading {}...", manifest_path);

    // 패키지 검증
    println!("Validating package...");

    // GOGS에 발행
    println!("Publishing to {}...", DEFAULT_REGISTRY_URL);

    CliResult::ok("Package published successfully")
        .with_details(vec![
            format!("Registry: {}", DEFAULT_REGISTRY_URL),
            "URL: https://gogs.dclub.kr/kim/my-project".to_string(),
            "Version tagged: v1.0.0".to_string(),
        ])
}

/// fpm list - 설치된 패키지 목록
pub fn cmd_list(manifest_path: &str) -> CliResult {
    // freelang.toml 읽기
    println!("Reading {}...", manifest_path);

    let packages = vec![
        "freelang-json@1.2.3".to_string(),
        "freelang-http@2.1.0".to_string(),
        "freelang-crypto@1.0.5".to_string(),
    ];

    CliResult::ok("Installed packages")
        .with_details(packages)
}

/// fpm search - 레지스트리에서 패키지 검색
pub fn cmd_search(query: &str) -> CliResult {
    // 레지스트리 검색
    match registry::search_package(DEFAULT_REGISTRY_URL, query) {
        Ok(result) => {
            let details = result
                .packages
                .iter()
                .map(|pkg| {
                    format!(
                        "  {} ({}): {}",
                        pkg.name, pkg.version, pkg.description
                    )
                })
                .collect();

            CliResult::ok(&format!(
                "Found {} package(s) matching '{}'",
                result.total, query
            ))
            .with_details(details)
        }
        Err(e) => {
            CliResult::error(&format!("Search failed: {}", e))
        }
    }
}

