   260→        let final_results = results.lock().unwrap();
   261→
   262→        assert_eq!(final_results.len(), 5);
   263→        // 모든 값이 짝수여야 함
   264→        for &val in final_results.iter() {
   265→            assert_eq!(val % 2, 0);
   266→        }
   267→    }
   268→
   269→    #[test]
   270→    fn test_threadpool_panic_handling() {
   271→        let pool = ThreadPool::new(2);
   272→        let counter = Arc::new(Mutex::new(0));
   273→
   274→        // 정상 작업
   275→        let counter_clone = Arc::clone(&counter);
   276→        pool.execute(move || {
   277→            let mut count = counter_clone.lock().unwrap();
   278→            *count += 1;
   279→        });
   280→
   281→        // Panic 작업 (캐치되지 않으므로 스레드 종료)
   282→        pool.execute(|| {
   283→            // panic!("test panic");  // 실제 panic은 스레드 kill
   284→        });
   285→
   286→        // 정상 작업
   287→        let counter_clone = Arc::clone(&counter);
   288→        pool.execute(move || {
   289→            let mut count = counter_clone.lock().unwrap();
   290→            *count += 1;
   291→        });
   292→
   293→        std::thread::sleep(std::time::Duration::from_millis(100));
   294→        let final_count = *counter.lock().unwrap();
   295→        assert!(final_count >= 2);  // 최소 2개는 실행
   296→    }
   297→
   298→    #[test]
   299→    fn test_threadpool_drop() {
   300→        let pool = ThreadPool::new(2);
   301→        let counter = Arc::new(Mutex::new(0));
   302→
   303→        for _ in 0..10 {
   304→            let counter_clone = Arc::clone(&counter);
   305→            pool.execute(move || {
   306→                let mut count = counter_clone.lock().unwrap();
   307→                *count += 1;
   308→            });
   309→        }
   310→
   311→        drop(pool);  // Drop 호출
   312→
   313→        std::thread::sleep(std::time::Duration::from_millis(100));
   314→        // Drop 후에도 모든 작업이 완료되어야 함
   315→        assert!(*counter.lock().unwrap() > 0);
   316→    }
   317→
   318→    #[test]
   319→    fn test_threadpool_heavy_work() {
   320→        let pool = ThreadPool::new(4);
   321→        let results = Arc::new(Mutex::new(Vec::new()));
   322→
   323→        for i in 0..20 {
   324→            let results_clone = Arc::clone(&results);
   325→            pool.execute(move || {
   326→                // 실제 작업 시뮬레이션
   327→                let mut sum = 0;
   328→                for j in 0..1000 {
   329→                    sum += j;
   330→                }
   331→
   332→                let mut res = results_clone.lock().unwrap();
   333→                res.push((i, sum));
   334→            });
   335→        }
   336→
   337→        std::thread::sleep(std::time::Duration::from_millis(500));
   338→        let final_results = results.lock().unwrap();
   339→
   340→        assert_eq!(final_results.len(), 20);
   341→    }
   342→}
