// ============================================================================
// FreeLang Runtime - Lexer & Parser
// ============================================================================
//
// Phase E Week 1: 토크나이저 + 파서 구현
// .fl 소스 코드를 토큰 → AST로 변환
//
// 작성일: 2026-04-20
// 단계: Phase E (Week 1)

use std::collections::HashMap;

// ============================================================================
// Token 정의
// ============================================================================

#[derive(Clone, Debug, PartialEq)]
pub enum Token {
    // 리터럴
    Int(i64),
    Float(f64),
    Bool(bool),
    Str(String),
    Null,

    // 키워드 (15개)
    Let,
    Fn,
    If,
    Else,
    While,
    For,
    Return,
    Use,
    Match,
    True,
    False,
    Break,
    Continue,
    In,
    Struct,

    // 연산자 (20개)
    Plus,
    Minus,
    Star,
    Slash,
    Percent,
    Eq,      // ==
    Neq,     // !=
    Lt,      // <
    Gt,      // >
    Le,      // <=
    Ge,      // >=
    And,     // &&
    Or,      // ||
    Not,     // !
    Assign,  // =
    PlusAssign,   // +=
    MinusAssign,  // -=
    Arrow,   // ->
    Ampersand,    // &

    // 구분자 (10개)
    LParen,
    RParen,
    LBrace,
    RBrace,
    LBracket,
    RBracket,
    Comma,
    Semicolon,
    Colon,
    Dot,

    // 특수
    Ident(String),
    EOF,
    Illegal(char),
}

impl std::fmt::Display for Token {
    fn fmt(&self, f: &mut std::fmt::Formatter) -> std::fmt::Result {
        match self {
            Token::Int(n) => write!(f, "INT({})", n),
            Token::Float(n) => write!(f, "FLOAT({})", n),
            Token::Bool(b) => write!(f, "BOOL({})", b),
            Token::Str(s) => write!(f, "STR({})", s),
            Token::Ident(s) => write!(f, "IDENT({})", s),
            _ => write!(f, "{:?}", self),
        }
    }
}

// ============================================================================
// Lexer 구현
// ============================================================================

pub struct Lexer {
    input: Vec<char>,
    pos: usize,
    line: usize,
    col: usize,
}

impl Lexer {
    pub fn new(input: &str) -> Self {
        Lexer {
            input: input.chars().collect(),
            pos: 0,
            line: 1,
            col: 1,
        }
    }

    fn current_char(&self) -> Option<char> {
        if self.pos < self.input.len() {
            Some(self.input[self.pos])
        } else {
            None
        }
    }

    fn peek_char(&self, offset: usize) -> Option<char> {
        let pos = self.pos + offset;
        if pos < self.input.len() {
            Some(self.input[pos])
        } else {
            None
        }
    }

    fn advance(&mut self) {
        if self.pos < self.input.len() {
            if self.input[self.pos] == '\n' {
                self.line += 1;
                self.col = 1;
            } else {
                self.col += 1;
            }
            self.pos += 1;
        }
    }

    fn skip_whitespace(&mut self) {
        while let Some(ch) = self.current_char() {
            if ch.is_whitespace() {
                self.advance();
            } else if ch == '/' && self.peek_char(1) == Some('/') {
                // 주석 건너뛰기
                while self.current_char().is_some() && self.current_char() != Some('\n') {
                    self.advance();
                }
            } else {
                break;
            }
        }
    }

    fn read_number(&mut self) -> Token {
        let mut num_str = String::new();
        let mut is_float = false;

        while let Some(ch) = self.current_char() {
            if ch.is_numeric() {
                num_str.push(ch);
                self.advance();
            } else if ch == '.' && !is_float {
                is_float = true;
                num_str.push(ch);
                self.advance();
            } else {
                break;
            }
        }

        if is_float {
            Token::Float(num_str.parse::<f64>().unwrap_or(0.0))
        } else {
            Token::Int(num_str.parse::<i64>().unwrap_or(0))
        }
    }

    fn read_string(&mut self, quote: char) -> Token {
        let mut s = String::new();
        self.advance(); // 시작 따옴표 건너뛰기

        while let Some(ch) = self.current_char() {
            if ch == quote {
                self.advance();
                break;
            } else if ch == '\\' {
                self.advance();
                match self.current_char() {
                    Some('n') => s.push('\n'),
                    Some('t') => s.push('\t'),
                    Some('r') => s.push('\r'),
                    Some('\\') => s.push('\\'),
                    Some('"') => s.push('"'),
                    Some('\'') => s.push('\''),
                    Some(c) => s.push(c),
                    None => break,
                }
                self.advance();
            } else {
                s.push(ch);
                self.advance();
            }
        }

        Token::Str(s)
    }

    fn read_ident(&mut self) -> Token {
        let mut ident = String::new();

        while let Some(ch) = self.current_char() {
            if ch.is_alphanumeric() || ch == '_' {
                ident.push(ch);
                self.advance();
            } else {
                break;
            }
        }

        // 키워드 확인
        match ident.as_str() {
            "let" => Token::Let,
            "fn" => Token::Fn,
            "if" => Token::If,
            "else" => Token::Else,
            "while" => Token::While,
            "for" => Token::For,
            "return" => Token::Return,
            "use" => Token::Use,
            "match" => Token::Match,
            "true" => Token::Bool(true),
            "false" => Token::Bool(false),
            "break" => Token::Break,
            "continue" => Token::Continue,
            "in" => Token::In,
            "struct" => Token::Struct,
            "null" => Token::Null,
            _ => Token::Ident(ident),
        }
    }

    pub fn next_token(&mut self) -> Token {
        self.skip_whitespace();

        match self.current_char() {
            None => Token::EOF,

            Some(ch) if ch.is_numeric() => self.read_number(),

            Some(ch) if ch.is_alphabetic() || ch == '_' => self.read_ident(),

            Some('"') => self.read_string('"'),
            Some('\'') => self.read_string('\''),

            // 연산자 & 구분자
            Some('+') => {
                self.advance();
                if self.current_char() == Some('=') {
                    self.advance();
                    Token::PlusAssign
                } else {
                    Token::Plus
                }
            }

            Some('-') => {
                self.advance();
                if self.current_char() == Some('=') {
                    self.advance();
                    Token::MinusAssign
                } else if self.current_char() == Some('>') {
                    self.advance();
                    Token::Arrow
                } else {
                    Token::Minus
                }
            }

            Some('*') => {
                self.advance();
                Token::Star
            }

            Some('/') => {
                self.advance();
                Token::Slash
            }

            Some('%') => {
                self.advance();
                Token::Percent
            }

            Some('=') => {
                self.advance();
                if self.current_char() == Some('=') {
                    self.advance();
                    Token::Eq
                } else {
                    Token::Assign
                }
            }

            Some('!') => {
                self.advance();
                if self.current_char() == Some('=') {
                    self.advance();
                    Token::Neq
                } else {
                    Token::Not
                }
            }

            Some('<') => {
                self.advance();
                if self.current_char() == Some('=') {
                    self.advance();
                    Token::Le
                } else {
                    Token::Lt
                }
            }

            Some('>') => {
                self.advance();
                if self.current_char() == Some('=') {
                    self.advance();
                    Token::Ge
                } else {
                    Token::Gt
                }
            }

            Some('&') => {
                self.advance();
                if self.current_char() == Some('&') {
                    self.advance();
                    Token::And
                } else {
                    Token::Ampersand
                }
            }

            Some('|') => {
                self.advance();
                if self.current_char() == Some('|') {
                    self.advance();
                    Token::Or
                } else {
                    Token::Illegal('|')
                }
            }

            Some('(') => {
                self.advance();
                Token::LParen
            }

            Some(')') => {
                self.advance();
                Token::RParen
            }

            Some('{') => {
                self.advance();
                Token::LBrace
            }

            Some('}') => {
                self.advance();
                Token::RBrace
            }

            Some('[') => {
                self.advance();
                Token::LBracket
            }

            Some(']') => {
                self.advance();
                Token::RBracket
            }

            Some(',') => {
                self.advance();
                Token::Comma
            }

            Some(';') => {
                self.advance();
                Token::Semicolon
            }

            Some(':') => {
                self.advance();
                Token::Colon
            }

            Some('.') => {
                self.advance();
                Token::Dot
            }

            Some(ch) => {
                self.advance();
                Token::Illegal(ch)
            }
        }
    }

    pub fn tokenize(&mut self) -> Vec<Token> {
        let mut tokens = vec![];
        loop {
            let token = self.next_token();
            let is_eof = token == Token::EOF;
            tokens.push(token);
            if is_eof {
                break;
            }
        }
        tokens
    }
}

// ============================================================================
// AST 정의
// ============================================================================

#[derive(Clone, Debug)]
pub enum BinOpKind {
    Add, Sub, Mul, Div, Mod,
    Eq, Neq, Lt, Gt, Le, Ge,
    And, Or,
}

#[derive(Clone, Debug)]
pub enum UnaryOpKind {
    Not, Neg,
}

#[derive(Clone, Debug)]
pub enum Expr {
    Int(i64),
    Float(f64),
    Bool(bool),
    Str(String),
    Null,
    Ident(String),
    BinOp {
        left: Box<Expr>,
        op: BinOpKind,
        right: Box<Expr>,
    },
    UnaryOp {
        op: UnaryOpKind,
        operand: Box<Expr>,
    },
    Call {
        func: String,
        args: Vec<Expr>,
    },
    Index {
        obj: Box<Expr>,
        index: Box<Expr>,
    },
    Array(Vec<Expr>),
    Object(Vec<(String, Expr)>),
    If {
        cond: Box<Expr>,
        then_block: Vec<Stmt>,
        else_block: Option<Vec<Stmt>>,
    },
}

#[derive(Clone, Debug)]
pub enum Stmt {
    Let {
        name: String,
        value: Expr,
    },
    Return(Expr),
    Expr(Expr),
    While {
        cond: Expr,
        body: Vec<Stmt>,
    },
    For {
        var: String,
        iter: Expr,
        body: Vec<Stmt>,
    },
}

#[derive(Clone, Debug)]
pub struct Program {
    pub stmts: Vec<Stmt>,
}

// ============================================================================
// Parser 구현
// ============================================================================

pub struct Parser {
    tokens: Vec<Token>,
    pos: usize,
}

impl Parser {
    pub fn new(tokens: Vec<Token>) -> Self {
        Parser { tokens, pos: 0 }
    }

    fn current_token(&self) -> Token {
        self.tokens.get(self.pos).cloned().unwrap_or(Token::EOF)
    }

    fn peek_token(&self) -> Token {
        self.tokens.get(self.pos + 1).cloned().unwrap_or(Token::EOF)
    }

    fn advance(&mut self) {
        if self.pos < self.tokens.len() {
            self.pos += 1;
        }
    }

    fn expect(&mut self, expected: Token) -> Result<(), String> {
        if std::mem::discriminant(&self.current_token()) == std::mem::discriminant(&expected) {
            self.advance();
            Ok(())
        } else {
            Err(format!("Expected {:?}, got {:?}", expected, self.current_token()))
        }
    }

    pub fn parse(&mut self) -> Result<Program, String> {
        let mut stmts = vec![];

        while self.current_token() != Token::EOF {
            stmts.push(self.parse_stmt()?);
        }

        Ok(Program { stmts })
    }

    fn parse_stmt(&mut self) -> Result<Stmt, String> {
        match &self.current_token() {
            Token::Let => self.parse_let(),
            Token::Return => self.parse_return(),
            Token::While => self.parse_while(),
            Token::For => self.parse_for(),
            _ => {
                let expr = self.parse_expr()?;
                if self.current_token() == Token::Semicolon {
                    self.advance();
                }
                Ok(Stmt::Expr(expr))
            }
        }
    }

    fn parse_let(&mut self) -> Result<Stmt, String> {
        self.expect(Token::Let)?;

        let name = match self.current_token() {
            Token::Ident(n) => {
                self.advance();
                n
            }
            _ => return Err("Expected identifier after let".to_string()),
        };

        self.expect(Token::Assign)?;
        let value = self.parse_expr()?;

        if self.current_token() == Token::Semicolon {
            self.advance();
        }

        Ok(Stmt::Let { name, value })
    }

    fn parse_return(&mut self) -> Result<Stmt, String> {
        self.expect(Token::Return)?;
        let expr = self.parse_expr()?;

        if self.current_token() == Token::Semicolon {
            self.advance();
        }

        Ok(Stmt::Return(expr))
    }

    fn parse_while(&mut self) -> Result<Stmt, String> {
        self.expect(Token::While)?;
        let cond = self.parse_expr()?;
        self.expect(Token::LBrace)?;
        let body = self.parse_block()?;
        self.expect(Token::RBrace)?;

        Ok(Stmt::While { cond, body })
    }

    fn parse_for(&mut self) -> Result<Stmt, String> {
        self.expect(Token::For)?;

        let var = match self.current_token() {
            Token::Ident(v) => {
                self.advance();
                v
            }
            _ => return Err("Expected variable name in for loop".to_string()),
        };

        self.expect(Token::In)?;
        let iter = self.parse_expr()?;
        self.expect(Token::LBrace)?;
        let body = self.parse_block()?;
        self.expect(Token::RBrace)?;

        Ok(Stmt::For { var, iter, body })
    }

    fn parse_block(&mut self) -> Result<Vec<Stmt>, String> {
        let mut stmts = vec![];

        while self.current_token() != Token::RBrace && self.current_token() != Token::EOF {
            stmts.push(self.parse_stmt()?);
        }

        Ok(stmts)
    }

    fn parse_expr(&mut self) -> Result<Expr, String> {
        self.parse_or()
    }

    fn parse_or(&mut self) -> Result<Expr, String> {
        let mut left = self.parse_and()?;

        while self.current_token() == Token::Or {
            self.advance();
            let right = self.parse_and()?;
            left = Expr::BinOp {
                left: Box::new(left),
                op: BinOpKind::Or,
                right: Box::new(right),
            };
        }

        Ok(left)
    }

    fn parse_and(&mut self) -> Result<Expr, String> {
        let mut left = self.parse_eq()?;

        while self.current_token() == Token::And {
            self.advance();
            let right = self.parse_eq()?;
            left = Expr::BinOp {
                left: Box::new(left),
                op: BinOpKind::And,
                right: Box::new(right),
            };
        }

        Ok(left)
    }

    fn parse_eq(&mut self) -> Result<Expr, String> {
        let mut left = self.parse_cmp()?;

        loop {
            let op = match &self.current_token() {
                Token::Eq => BinOpKind::Eq,
                Token::Neq => BinOpKind::Neq,
                _ => break,
            };
            self.advance();
            let right = self.parse_cmp()?;
            left = Expr::BinOp {
                left: Box::new(left),
                op,
                right: Box::new(right),
            };
        }

        Ok(left)
    }

    fn parse_cmp(&mut self) -> Result<Expr, String> {
        let mut left = self.parse_add()?;

        loop {
            let op = match &self.current_token() {
                Token::Lt => BinOpKind::Lt,
                Token::Gt => BinOpKind::Gt,
                Token::Le => BinOpKind::Le,
                Token::Ge => BinOpKind::Ge,
                _ => break,
            };
            self.advance();
            let right = self.parse_add()?;
            left = Expr::BinOp {
                left: Box::new(left),
                op,
                right: Box::new(right),
            };
        }

        Ok(left)
    }

    fn parse_add(&mut self) -> Result<Expr, String> {
        let mut left = self.parse_mul()?;

        loop {
            let op = match &self.current_token() {
                Token::Plus => BinOpKind::Add,
                Token::Minus => BinOpKind::Sub,
                _ => break,
            };
            self.advance();
            let right = self.parse_mul()?;
            left = Expr::BinOp {
                left: Box::new(left),
                op,
                right: Box::new(right),
            };
        }

        Ok(left)
    }

    fn parse_mul(&mut self) -> Result<Expr, String> {
        let mut left = self.parse_unary()?;

        loop {
            let op = match &self.current_token() {
                Token::Star => BinOpKind::Mul,
                Token::Slash => BinOpKind::Div,
                Token::Percent => BinOpKind::Mod,
                _ => break,
            };
            self.advance();
            let right = self.parse_unary()?;
            left = Expr::BinOp {
                left: Box::new(left),
                op,
                right: Box::new(right),
            };
        }

        Ok(left)
    }

    fn parse_unary(&mut self) -> Result<Expr, String> {
        match &self.current_token() {
            Token::Not => {
                self.advance();
                let operand = self.parse_unary()?;
                Ok(Expr::UnaryOp {
                    op: UnaryOpKind::Not,
                    operand: Box::new(operand),
                })
            }
            Token::Minus => {
                self.advance();
                let operand = self.parse_unary()?;
                Ok(Expr::UnaryOp {
                    op: UnaryOpKind::Neg,
                    operand: Box::new(operand),
                })
            }
            _ => self.parse_postfix(),
        }
    }

    fn parse_postfix(&mut self) -> Result<Expr, String> {
        let mut expr = self.parse_primary()?;

        loop {
            match &self.current_token() {
                Token::LParen => {
                    // 함수 호출
                    if let Expr::Ident(func) = expr {
                        self.advance();
                        let args = self.parse_args()?;
                        self.expect(Token::RParen)?;
                        expr = Expr::Call { func, args };
                    } else {
                        return Err("Cannot call non-function".to_string());
                    }
                }
                Token::LBracket => {
                    // 인덱싱
                    self.advance();
                    let index = self.parse_expr()?;
                    self.expect(Token::RBracket)?;
                    expr = Expr::Index {
                        obj: Box::new(expr),
                        index: Box::new(index),
                    };
                }
                Token::Dot => {
                    // 멤버 접근 (간단히 처리)
                    self.advance();
                    if let Token::Ident(member) = self.current_token() {
                        self.advance();
                        // a.b를 a["b"] 인덱싱으로 변환
                        expr = Expr::Index {
                            obj: Box::new(expr),
                            index: Box::new(Expr::Str(member)),
                        };
                    }
                }
                _ => break,
            }
        }

        Ok(expr)
    }

    fn parse_args(&mut self) -> Result<Vec<Expr>, String> {
        let mut args = vec![];

        if self.current_token() == Token::RParen {
            return Ok(args);
        }

        loop {
            args.push(self.parse_expr()?);
            if self.current_token() == Token::Comma {
                self.advance();
            } else {
                break;
            }
        }

        Ok(args)
    }

    fn parse_primary(&mut self) -> Result<Expr, String> {
        match self.current_token() {
            Token::Int(n) => {
                self.advance();
                Ok(Expr::Int(n))
            }
            Token::Float(f) => {
                self.advance();
                Ok(Expr::Float(f))
            }
            Token::Bool(b) => {
                self.advance();
                Ok(Expr::Bool(b))
            }
            Token::Str(s) => {
                self.advance();
                Ok(Expr::Str(s))
            }
            Token::Null => {
                self.advance();
                Ok(Expr::Null)
            }
            Token::Ident(name) => {
                self.advance();
                Ok(Expr::Ident(name))
            }
            Token::LBracket => self.parse_array(),
            Token::LBrace => self.parse_object(),
            Token::LParen => {
                self.advance();
                let expr = self.parse_expr()?;
                self.expect(Token::RParen)?;
                Ok(expr)
            }
            Token::If => self.parse_if(),
            _ => Err(format!("Unexpected token: {:?}", self.current_token())),
        }
    }

    fn parse_array(&mut self) -> Result<Expr, String> {
        self.expect(Token::LBracket)?;
        let mut elements = vec![];

        if self.current_token() == Token::RBracket {
            self.advance();
            return Ok(Expr::Array(elements));
        }

        loop {
            elements.push(self.parse_expr()?);
            if self.current_token() == Token::Comma {
                self.advance();
            } else {
                break;
            }
        }

        self.expect(Token::RBracket)?;
        Ok(Expr::Array(elements))
    }

    fn parse_object(&mut self) -> Result<Expr, String> {
        self.expect(Token::LBrace)?;
        let mut pairs = vec![];

        if self.current_token() == Token::RBrace {
            self.advance();
            return Ok(Expr::Object(pairs));
        }

        loop {
            let key = match self.current_token() {
                Token::Str(s) => {
                    self.advance();
                    s
                }
                Token::Ident(s) => {
                    self.advance();
                    s
                }
                _ => return Err("Expected object key".to_string()),
            };

            self.expect(Token::Colon)?;
            let value = self.parse_expr()?;
            pairs.push((key, value));

            if self.current_token() == Token::Comma {
                self.advance();
            } else {
                break;
            }
        }

        self.expect(Token::RBrace)?;
        Ok(Expr::Object(pairs))
    }

    fn parse_if(&mut self) -> Result<Expr, String> {
        self.expect(Token::If)?;
        let cond = self.parse_expr()?;
        self.expect(Token::LBrace)?;
        let then_block = self.parse_block()?;
        self.expect(Token::RBrace)?;

        let else_block = if self.current_token() == Token::Else {
            self.advance();
            self.expect(Token::LBrace)?;
            let block = self.parse_block()?;
            self.expect(Token::RBrace)?;
            Some(block)
        } else {
            None
        };

        Ok(Expr::If {
            cond: Box::new(cond),
            then_block,
            else_block,
        })
    }
}

