}

// ============================================================================
// IO Functions
// ============================================================================

fn builtin_println(args: Vec<FlValue>, _env: &mut Environment) -> Result<FlValue, RuntimeError> {
    for arg in args {
        println!("{}", arg);
    }
    Ok(FlValue::Null)
}

fn builtin_print(args: Vec<FlValue>, _env: &mut Environment) -> Result<FlValue, RuntimeError> {
    for (i, arg) in args.iter().enumerate() {
        if i > 0 {
            print!(" ");
        }
        print!("{}", arg);
    }
    Ok(FlValue::Null)
}

fn builtin_read_file(args: Vec<FlValue>, _env: &mut Environment) -> Result<FlValue, RuntimeError> {
    if args.len() != 1 {
        return Err(RuntimeError::CallError {
            name: "read_file".to_string(),
            reason: "Expected 1 argument".to_string(),
        });
    }

    let path = match &args[0] {
        FlValue::Str(s) => s,
        _ => return Err(RuntimeError::TypeError {
            expected: "string".to_string(),
            got: args[0].type_name().to_string(),
            context: "read_file".to_string(),
        }),
    };

    match std::fs::read_to_string(path) {
        Ok(content) => Ok(FlValue::Str(content)),
        Err(e) => Err(RuntimeError::Other(format!("File read error: {}", e))),
    }
}

fn builtin_write_file(args: Vec<FlValue>, _env: &mut Environment) -> Result<FlValue, RuntimeError> {
    if args.len() != 2 {
        return Err(RuntimeError::CallError {
            name: "write_file".to_string(),
            reason: "Expected 2 arguments".to_string(),
        });
    }

    let path = match &args[0] {
        FlValue::Str(s) => s.clone(),
        _ => return Err(RuntimeError::TypeError {
            expected: "string".to_string(),
            got: args[0].type_name().to_string(),
            context: "write_file".to_string(),
        }),
    };

    let content = args[1].to_string_repr();

    match std::fs::write(path, content) {
        Ok(_) => Ok(FlValue::Null),
        Err(e) => Err(RuntimeError::Other(format!("File write error: {}", e))),
    }
}

// ============================================================================
// String Functions
// ============================================================================

fn builtin_str_length(args: Vec<FlValue>, _env: &mut Environment) -> Result<FlValue, RuntimeError> {
    if args.len() != 1 {
        return Err(RuntimeError::CallError {
            name: "str_length".to_string(),
            reason: "Expected 1 argument".to_string(),
        });
    }

    let len = match &args[0] {
        FlValue::Str(s) => s.len() as i64,
        _ => return Err(RuntimeError::TypeError {
            expected: "string".to_string(),
            got: args[0].type_name().to_string(),
            context: "str_length".to_string(),
        }),
    };

    Ok(FlValue::Int(len))
}

fn builtin_str_concat(args: Vec<FlValue>, _env: &mut Environment) -> Result<FlValue, RuntimeError> {
    let mut result = String::new();

    for arg in args {
        match arg {
            FlValue::Str(s) => result.push_str(&s),
            _ => result.push_str(&arg.to_string_repr()),
        }
    }

    Ok(FlValue::Str(result))
}

fn builtin_str_split(args: Vec<FlValue>, _env: &mut Environment) -> Result<FlValue, RuntimeError> {
    if args.len() != 2 {
        return Err(RuntimeError::CallError {
            name: "str_split".to_string(),
            reason: "Expected 2 arguments".to_string(),
        });
    }

    let s = match &args[0] {
        FlValue::Str(s) => s,
        _ => return Err(RuntimeError::TypeError {
            expected: "string".to_string(),
            got: args[0].type_name().to_string(),
            context: "str_split".to_string(),
        }),
    };

    let sep = match &args[1] {
        FlValue::Str(s) => s,
        _ => return Err(RuntimeError::TypeError {
            expected: "string".to_string(),
            got: args[1].type_name().to_string(),
            context: "str_split".to_string(),
        }),
    };

    let parts: Vec<FlValue> = s.split(sep.as_str())
        .map(|s| FlValue::Str(s.to_string()))
        .collect();

    Ok(FlValue::Array(parts))
}

fn builtin_str_format(args: Vec<FlValue>, _env: &mut Environment) -> Result<FlValue, RuntimeError> {
    if args.is_empty() {
        return Err(RuntimeError::CallError {
            name: "str_format".to_string(),
            reason: "Expected at least 1 argument".to_string(),
        });
    }

    let format_str = match &args[0] {
        FlValue::Str(s) => s.clone(),
        _ => return Err(RuntimeError::TypeError {
            expected: "string".to_string(),
            got: args[0].type_name().to_string(),
            context: "str_format".to_string(),
        }),
    };

    // 간단한 치환: {} 패턴을 인수로 치환
    let mut result = format_str;
    for arg in &args[1..] {
        if let Some(pos) = result.find("{}") {
            result.replace_range(pos..pos+2, &arg.to_string_repr());
        }
    }

    Ok(FlValue::Str(result))
}

fn builtin_str_upper(args: Vec<FlValue>, _env: &mut Environment) -> Result<FlValue, RuntimeError> {
    if args.len() != 1 {
        return Err(RuntimeError::CallError {
            name: "str_upper".to_string(),
            reason: "Expected 1 argument".to_string(),
        });
    }

    let s = match &args[0] {
        FlValue::Str(s) => s.to_uppercase(),
        _ => return Err(RuntimeError::TypeError {
            expected: "string".to_string(),
            got: args[0].type_name().to_string(),
            context: "str_upper".to_string(),
        }),
    };

    Ok(FlValue::Str(s))
}

fn builtin_str_lower(args: Vec<FlValue>, _env: &mut Environment) -> Result<FlValue, RuntimeError> {
    if args.len() != 1 {
        return Err(RuntimeError::CallError {
            name: "str_lower".to_string(),
            reason: "Expected 1 argument".to_string(),
        });
    }

    let s = match &args[0] {
        FlValue::Str(s) => s.to_lowercase(),
        _ => return Err(RuntimeError::TypeError {
            expected: "string".to_string(),
            got: args[0].type_name().to_string(),
            context: "str_lower".to_string(),
        }),
    };

    Ok(FlValue::Str(s))
}

fn builtin_str_trim(args: Vec<FlValue>, _env: &mut Environment) -> Result<FlValue, RuntimeError> {
    if args.len() != 1 {
        return Err(RuntimeError::CallError {
            name: "str_trim".to_string(),
            reason: "Expected 1 argument".to_string(),
        });
    }

    let s = match &args[0] {
        FlValue::Str(s) => s.trim().to_string(),
        _ => return Err(RuntimeError::TypeError {
            expected: "string".to_string(),
            got: args[0].type_name().to_string(),
            context: "str_trim".to_string(),
        }),
    };

    Ok(FlValue::Str(s))
}

fn builtin_str_replace(args: Vec<FlValue>, _env: &mut Environment) -> Result<FlValue, RuntimeError> {
    if args.len() != 3 {
        return Err(RuntimeError::CallError {
            name: "str_replace".to_string(),
            reason: "Expected 3 arguments".to_string(),
        });
    }

    let s = match &args[0] {
        FlValue::Str(s) => s,
        _ => return Err(RuntimeError::TypeError {
            expected: "string".to_string(),
            got: args[0].type_name().to_string(),
            context: "str_replace".to_string(),
        }),
    };

    let from = match &args[1] {
        FlValue::Str(s) => s,
        _ => return Err(RuntimeError::TypeError {
            expected: "string".to_string(),
            got: args[1].type_name().to_string(),
            context: "str_replace".to_string(),
        }),
    };

    let to = match &args[2] {
        FlValue::Str(s) => s,
        _ => return Err(RuntimeError::TypeError {
            expected: "string".to_string(),
            got: args[2].type_name().to_string(),
            context: "str_replace".to_string(),
        }),
    };

    Ok(FlValue::Str(s.replace(from.as_str(), to.as_str())))
}

// ============================================================================
// Array Functions
// ============================================================================

fn builtin_array_push(args: Vec<FlValue>, _env: &mut Environment) -> Result<FlValue, RuntimeError> {
    if args.len() != 2 {
        return Err(RuntimeError::CallError {
            name: "array_push".to_string(),
            reason: "Expected 2 arguments".to_string(),
        });
    }

    let mut arr = match &args[0] {
        FlValue::Array(a) => a.clone(),
        _ => return Err(RuntimeError::TypeError {
            expected: "array".to_string(),
            got: args[0].type_name().to_string(),
            context: "array_push".to_string(),
        }),
    };

    arr.push(args[1].clone());
    Ok(FlValue::Array(arr))
}

fn builtin_array_pop(args: Vec<FlValue>, _env: &mut Environment) -> Result<FlValue, RuntimeError> {
    if args.len() != 1 {
        return Err(RuntimeError::CallError {
            name: "array_pop".to_string(),
            reason: "Expected 1 argument".to_string(),
        });
    }

    let mut arr = match &args[0] {
        FlValue::Array(a) => a.clone(),
        _ => return Err(RuntimeError::TypeError {
            expected: "array".to_string(),
            got: args[0].type_name().to_string(),
            context: "array_pop".to_string(),
        }),
    };

    let popped = arr.pop().unwrap_or(FlValue::Null);
    Ok(popped)
}

fn builtin_array_length(args: Vec<FlValue>, _env: &mut Environment) -> Result<FlValue, RuntimeError> {
    if args.len() != 1 {
        return Err(RuntimeError::CallError {
            name: "array_length".to_string(),
            reason: "Expected 1 argument".to_string(),
        });
    }

    let len = match &args[0] {
        FlValue::Array(a) => a.len() as i64,
        _ => return Err(RuntimeError::TypeError {
            expected: "array".to_string(),
            got: args[0].type_name().to_string(),
            context: "array_length".to_string(),
        }),
    };

    Ok(FlValue::Int(len))
}

fn builtin_array_map(args: Vec<FlValue>, _env: &mut Environment) -> Result<FlValue, RuntimeError> {
    if args.len() != 2 {
        return Err(RuntimeError::CallError {
            name: "array_map".to_string(),
            reason: "Expected 2 arguments".to_string(),
        });
    }

    let arr = match &args[0] {
        FlValue::Array(a) => a,
        _ => return Err(RuntimeError::TypeError {
            expected: "array".to_string(),
            got: args[0].type_name().to_string(),
            context: "array_map".to_string(),
        }),
    };

    // 간단한 map: 각 원소를 2배로
    let result: Vec<FlValue> = arr.iter()
        .map(|item| {
            match item {
                FlValue::Int(n) => FlValue::Int(n * 2),
                FlValue::Float(f) => FlValue::Float(f * 2.0),
                _ => item.clone(),
            }
        })
        .collect();

    Ok(FlValue::Array(result))
}

