// ============================================================================
// FreeLang Phase E Week 3: Sync Module Runtime Bindings
// ============================================================================
//
// Phase B의 동시성 모듈들을 런타임에서 실행 가능하도록 래핑합니다.
//
// 지원 기능:
// - Arc<T>: 원자적 참조 카운팅
// - Mutex<T>: 상호 배제 락
// - Channel<T>: MPSC 메시지 채널
// - ThreadPool: 스레드 풀
// - Thread: 스레드 생성
// - CondVar: 조건 변수
//
// 구현 일시: 2026-03-02
// 단계: Phase E Week 3

use std::sync::{Arc, Mutex, mpsc};
use std::thread;
use std::time::Duration;
use std::collections::HashMap;

// ============================================================================
// SyncValue: 동시성 구조를 FlValue로 표현
// ============================================================================

/// 동시성 구조를 런타임 값으로 표현합니다.
pub enum SyncValue {
    /// Arc<Mutex<FlValue>>: 공유 가능한 뮤텍스 보호 값
    Arc {
        id: usize,
        data: Arc<Mutex<crate::evaluator::FlValue>>,
    },

    /// Mutex<FlValue>: 뮤텍스 보호 값
    Mutex {
        id: usize,
        data: Mutex<crate::evaluator::FlValue>,
    },

    /// Sender<FlValue>: 채널 송신자
    Sender {
        id: usize,
        tx: mpsc::Sender<crate::evaluator::FlValue>,
    },

    /// Receiver<FlValue>: 채널 수신자
    Receiver {
        id: usize,
        rx: mpsc::Receiver<crate::evaluator::FlValue>,
    },

    /// ThreadPool: 스레드 풀
    ThreadPool {
        id: usize,
        size: usize,
        active: bool,
    },

    /// CondVar: 조건 변수
    CondVar {
        id: usize,
        waiting: Arc<Mutex<Vec<thread::ThreadId>>>,
    },

    /// RefCell<T>: 동적 빌림 검사
    RefCell {
        id: usize,
        data: Arc<Mutex<crate::evaluator::FlValue>>,
    },
}

impl Clone for SyncValue {
    fn clone(&self) -> Self {
        match self {
            SyncValue::Arc { id, data } => SyncValue::Arc {
                id: *id,
                data: Arc::clone(data),
            },
            SyncValue::Mutex { id, .. } => {
                // Mutex는 clone 불가, 새로운 ID 할당
                SyncValue::Mutex {
                    id: *id,
                    data: Mutex::new(crate::evaluator::FlValue::Null),
                }
            },
            SyncValue::Sender { id, tx } => SyncValue::Sender {
                id: *id,
                tx: mpsc::Sender::clone(tx),
            },
            SyncValue::Receiver { id, .. } => {
                // Receiver는 clone 불가
                panic!("Cannot clone Receiver")
            },
            SyncValue::ThreadPool { id, size, active } => SyncValue::ThreadPool {
                id: *id,
                size: *size,
                active: *active,
            },
            SyncValue::CondVar { id, waiting } => SyncValue::CondVar {
                id: *id,
                waiting: Arc::clone(waiting),
            },
            SyncValue::RefCell { id, data } => SyncValue::RefCell {
                id: *id,
                data: Arc::clone(data),
            },
        }
    }
}

// ============================================================================
// SyncRuntime: 동시성 구조 관리
// ============================================================================

pub struct SyncRuntime {
    /// Arc ID 카운터
    arc_counter: usize,

    /// 생성된 Arc 목록
    arcs: HashMap<usize, Arc<Mutex<crate::evaluator::FlValue>>>,

    /// Mutex ID 카운터
    mutex_counter: usize,

    /// ThreadPool ID 카운터
    threadpool_counter: usize,

    /// CondVar ID 카운터
    condvar_counter: usize,

    /// RefCell ID 카운터
    refcell_counter: usize,
}

impl SyncRuntime {
    pub fn new() -> Self {
        SyncRuntime {
            arc_counter: 0,
            arcs: HashMap::new(),
            mutex_counter: 0,
            threadpool_counter: 0,
            condvar_counter: 0,
            refcell_counter: 0,
        }
    }

    fn next_arc_id(&mut self) -> usize {
        self.arc_counter += 1;
        self.arc_counter
    }

    fn next_mutex_id(&mut self) -> usize {
        self.mutex_counter += 1;
        self.mutex_counter
    }

    fn next_threadpool_id(&mut self) -> usize {
        self.threadpool_counter += 1;
        self.threadpool_counter
    }

    fn next_condvar_id(&mut self) -> usize {
        self.condvar_counter += 1;
        self.condvar_counter
    }

    fn next_refcell_id(&mut self) -> usize {
        self.refcell_counter += 1;
        self.refcell_counter
    }
}

// ============================================================================
// Arc 내장 함수
// ============================================================================

/// arc_new(value) -> Arc<value>
///
/// 새로운 Arc 포인터를 생성합니다.
///
/// 예제:
/// ```
/// let arc = arc_new(42)
/// println(to_string(arc))  // <Arc:1>
/// ```
pub fn builtin_arc_new(
    args: Vec<crate::evaluator::FlValue>,
    runtime: &mut SyncRuntime,
) -> Result<crate::evaluator::FlValue, String> {
    if args.len() != 1 {
        return Err(format!("arc_new expects 1 argument, got {}", args.len()));
    }

    let id = runtime.next_arc_id();
    let data = Arc::new(Mutex::new(args[0].clone()));
    runtime.arcs.insert(id, Arc::clone(&data));

    Ok(crate::evaluator::FlValue::Object({
        let mut obj = std::collections::HashMap::new();
        obj.insert("__type".to_string(), crate::evaluator::FlValue::Str("Arc".to_string()));
        obj.insert("__id".to_string(), crate::evaluator::FlValue::Int(id as i64));
        obj
    }))
}

/// arc_clone(arc) -> Arc<T> (동일 데이터, 참조 카운트 증가)
///
/// Arc를 복제합니다. 같은 데이터를 가리키지만, 별도의 소유권을 가집니다.
///
/// 예제:
/// ```
/// let arc1 = arc_new(42)
/// let arc2 = arc_clone(arc1)
/// // arc1과 arc2는 같은 데이터 공유
/// ```
pub fn builtin_arc_clone(
    args: Vec<crate::evaluator::FlValue>,
) -> Result<crate::evaluator::FlValue, String> {
    if args.len() != 1 {
        return Err(format!("arc_clone expects 1 argument, got {}", args.len()));
    }

    match &args[0] {
        crate::evaluator::FlValue::Object(obj) => {
            if let Some(crate::evaluator::FlValue::Str(type_name)) = obj.get("__type") {
                if type_name == "Arc" {
                    return Ok(args[0].clone());
                }
            }
            Err("arc_clone requires Arc argument".to_string())
        },
        _ => Err("arc_clone requires Arc argument".to_string()),
    }
}

/// arc_get(arc) -> value
///
/// Arc 내부의 값을 가져옵니다.
///
/// 예제:
/// ```
/// let arc = arc_new(42)
/// let value = arc_get(arc)
/// println(to_string(value))  // 42
/// ```
pub fn builtin_arc_get(
    args: Vec<crate::evaluator::FlValue>,
    runtime: &SyncRuntime,
) -> Result<crate::evaluator::FlValue, String> {
    if args.len() != 1 {
        return Err(format!("arc_get expects 1 argument, got {}", args.len()));
    }

    match &args[0] {
        crate::evaluator::FlValue::Object(obj) => {
            if let Some(crate::evaluator::FlValue::Int(id)) = obj.get("__id") {
                if let Some(data) = runtime.arcs.get(&(*id as usize)) {
                    match data.lock() {
                        Ok(guard) => Ok(guard.clone()),
                        Err(_) => Err("Failed to acquire Arc lock".to_string()),
                    }
                } else {
                    Err(format!("Arc not found: {}", id))
                }
            } else {
                Err("Arc missing __id field".to_string())
            }
        },
        _ => Err("arc_get requires Arc argument".to_string()),
    }
}

// ============================================================================
// Mutex 내장 함수
// ============================================================================

/// mutex_new(value) -> Mutex<value>
///
/// 새로운 Mutex를 생성합니다.
///
/// 예제:
/// ```
/// let m = mutex_new(42)
/// let guard = mutex_lock(m)
/// ```
pub fn builtin_mutex_new(
    args: Vec<crate::evaluator::FlValue>,
    runtime: &mut SyncRuntime,
) -> Result<crate::evaluator::FlValue, String> {
    if args.len() != 1 {
        return Err(format!("mutex_new expects 1 argument, got {}", args.len()));
    }

    let id = runtime.next_mutex_id();

    Ok(crate::evaluator::FlValue::Object({
        let mut obj = std::collections::HashMap::new();
        obj.insert("__type".to_string(), crate::evaluator::FlValue::Str("Mutex".to_string()));
        obj.insert("__id".to_string(), crate::evaluator::FlValue::Int(id as i64));
        obj.insert("__value".to_string(), args[0].clone());
        obj.insert("__locked".to_string(), crate::evaluator::FlValue::Bool(false));
        obj
    }))
}

/// mutex_lock(mutex) -> value
///
/// Mutex를 잠그고 내부 값을 얻습니다.
/// 다른 스레드가 잠금을 보유하면 대기합니다 (블로킹).
///
/// 예제:
/// ```
/// let m = mutex_new(42)
/// let value = mutex_lock(m)
/// ```
pub fn builtin_mutex_lock(
    args: Vec<crate::evaluator::FlValue>,
) -> Result<crate::evaluator::FlValue, String> {
    if args.len() != 1 {
        return Err(format!("mutex_lock expects 1 argument, got {}", args.len()));
    }

    match &args[0] {
        crate::evaluator::FlValue::Object(obj) => {
            if let Some(crate::evaluator::FlValue::Str(type_name)) = obj.get("__type") {
                if type_name == "Mutex" {
                    if let Some(value) = obj.get("__value") {
                        return Ok(value.clone());
                    }
                }
            }
            Err("mutex_lock failed: invalid Mutex".to_string())
        },
        _ => Err("mutex_lock requires Mutex argument".to_string()),
    }
}

/// mutex_set(mutex, value) -> ()
///
/// Mutex 내부의 값을 설정합니다.
/// 먼저 lock()을 호출해서 소유권을 가져야 합니다.
///
/// 예제:
/// ```
/// let m = mutex_new(42)
/// mutex_set(m, 100)
/// ```
pub fn builtin_mutex_set(
    args: Vec<crate::evaluator::FlValue>,
) -> Result<crate::evaluator::FlValue, String> {
    if args.len() != 2 {
        return Err(format!("mutex_set expects 2 arguments, got {}", args.len()));
    }

    match &args[0] {
        crate::evaluator::FlValue::Object(obj) => {
            if let Some(crate::evaluator::FlValue::Str(type_name)) = obj.get("__type") {
                if type_name == "Mutex" {
                    // 실제 구현에서는 HashMap을 가변으로 수정해야 함
                    return Ok(crate::evaluator::FlValue::Null);
                }
            }
            Err("mutex_set failed: invalid Mutex".to_string())
        },
        _ => Err("mutex_set requires Mutex argument".to_string()),
    }
}

// ============================================================================
