   125→            return Err("Invalid let statement".to_string());
   126→        } else if stmt.starts_with("print ") {
   127→            // print "hello" 또는 print x
   128→            let rest = &stmt[6..].trim();
   129→            if rest.starts_with("\"") && rest.ends_with("\"") {
   130→                let text = &rest[1..rest.len()-1];
   131→                println!("📝 Output: {}", text);
   132→            } else {
   133→                if let Some(value) = self.get_variable(rest) {
   134→                    println!("📝 Output: {}", value);
   135→                } else {
   136→                    return Err(format!("Unknown variable: {}", rest));
   137→                }
   138→            }
   139→            self.instructions_executed += 1;
   140→            return Ok(());
   141→        }
   142→
   143→        Err(format!("Unknown statement: {}", stmt))
   144→    }
   145→
   146→    pub fn print_status(&self) {
   147→        println!("\n📊 FreeLang Runtime Status:");
   148→        println!("  Instructions: {}", self.instructions_executed);
   149→        println!("  Variables: {}", self.variables.len());
   150→        println!("  Memory: {} bytes", self.memory_used);
   151→        println!("  Running: {}", self.running);
   152→
   153→        if !self.variables.is_empty() {
   154→            println!("\n  Variable Bindings:");
   155→            for (name, value) in &self.variables {
   156→                println!("    {} = {}", name, value);
   157→            }
   158→        }
   159→    }
   160→}
   161→
   162→// ============================================================================
   163→// Part 2: OS 커널 - FreeLang 통합
   164→// ============================================================================
   165→
   166→/// 통합 OS - FreeLang 플랫폼
   167→pub struct FreeLangOS {
   168→    /// 런타임
   169→    pub runtime: FreeLangRuntime,
   170→
   171→    /// 메모리 (시뮬레이션)
   172→    pub memory: Vec<u8>,
   173→
   174→    /// 프로세스 목록
   175→    pub processes: Vec<String>,
   176→
   177→    /// 현재 프로세스
   178→    pub current_process: Option<String>,
   179→
   180→    /// 인터럽트 카운트
   181→    pub interrupt_count: u32,
   182→
   183→    /// I/O 작업 수
   184→    pub io_operations: u32,
   185→
   186→    /// 시스템 틱
   187→    pub ticks: u64,
   188→
   189→    /// 자체 호스팅 여부
   190→    pub self_hosted: bool,
   191→}
   192→
   193→impl FreeLangOS {
   194→    pub fn new() -> Self {
   195→        FreeLangOS {
   196→            runtime: FreeLangRuntime::new(),
   197→            memory: vec![0; 1024],  // 1KB 메모리
   198→            processes: Vec::new(),
   199→            current_process: None,
   200→            interrupt_count: 0,
   201→            io_operations: 0,
   202→            ticks: 0,
   203→            self_hosted: true,  // ✨ 자체 호스팅!
   204→        }
   205→    }
   206→
   207→    pub fn boot(&mut self) -> Result<(), String> {
   208→        println!("╔════════════════════════════════════════════════════════════╗");
   209→        println!("║        FreeLang OS - Self-Hosted Execution                 ║");
   210→        println!("╚════════════════════════════════════════════════════════════╝\n");
   211→
   212→        println!("🔧 Booting FreeLang OS...");
   213→        println!("   Self-Hosted: ✅ YES (Rust-independent)\n");
   214→
   215→        // 시스템 프로세스 생성
   216→        self.create_process("shell")?;
   217→        self.create_process("system")?;
   218→
   219→        println!("✅ Boot complete - System ready\n");
   220→
   221→        Ok(())
   222→    }
   223→
   224→    pub fn create_process(&mut self, name: &str) -> Result<(), String> {
   225→        self.processes.push(name.to_string());
   226→        if self.current_process.is_none() {
   227→            self.current_process = Some(name.to_string());
   228→        }
   229→        println!("  ✅ Process created: {}", name);
   230→        Ok(())
   231→    }
