   233→    pub fn run_freelang_program(&mut self, program: Vec<&str>) -> Result<(), String> {
   234→        println!("🚀 Executing FreeLang Program...\n");
   235→
   236→        for (idx, stmt) in program.iter().enumerate() {
   237→            println!("[{}] {}", idx + 1, stmt);
   238→
   239→            self.runtime.execute_statement(stmt)?;
   240→            self.ticks += 1;
   241→
   242→            // 시뮬레이션된 I/O
   243→            if stmt.contains("print") {
   244→                self.io_operations += 1;
   245→            }
   246→        }
   247→
   248→        println!("\n✅ Program execution complete\n");
   249→        Ok(())
   250→    }
   251→
   252→    pub fn interrupt(&mut self, _int_type: u8) {
   253→        self.interrupt_count += 1;
   254→        self.ticks += 1;
   255→    }
   256→
   257→    pub fn print_system_status(&self) {
