   267→
   268→        println!("\n🔄 Processes ({}):", self.processes.len());
   269→        for (idx, proc) in self.processes.iter().enumerate() {
   270→            let marker = if self.current_process.as_ref() == Some(proc) {
   271→                "▶️ "
   272→            } else {
   273→                "⏸️ "
   274→            };
   275→            println!("  {} {} (Process {})", marker, proc, idx + 1);
   276→        }
   277→
   278→        println!("\n💾 Memory Usage:");
