   383→        println!("  Own Scheduler: {}", if self.own_scheduler { "✅ YES" } else { "❌ NO" });
   384→        println!("  Own I/O: {}", if self.own_io { "✅ YES" } else { "❌ NO" });
   385→        println!("  Own Interrupts: {}", if self.own_interrupts { "✅ YES" } else { "❌ NO" });
   386→
